def link_depends(a: Pkg, b: Pkg) { a +>:Depends:+> b; }
def link_contains(a: Pkg, b: Pkg) { a +>:Contains:+> b; }
def link_registers(w: Workflow, c: Capability) { w +>:Registers:+> c; }
def link_cap_depends(a: Capability, b: Capability) { a +>:Depends:+> b; }

def get_transitive_deps(start: Pkg) -> list[str] {
    w = start spawn PkgClosure();
    res: list[str] = [];
    for p in w.collected { if p != start.pid { res.append(p); } }
    return sorted(res);
}
def get_workflow_caps(start: Workflow) -> list[str] {
    w = start spawn WorkflowCapClosure();
    return sorted(w.caps);
}
def is_pkg_reachable(start: Pkg, target_pid: str) -> bool {
    if start.pid == target_pid { return True; }
    deps: list[str] = get_transitive_deps(start);
    for d in deps { if d == target_pid { return True; } }
    return False;
}
def can_workflow_expose(start: Workflow, target_cid: str) -> bool {
    caps: list[str] = get_workflow_caps(start);
    for c in caps { if c == target_cid { return True; } }
    return False;
}

