def create_world(entry_cid: str) -> StoryGraph {
    g = StoryGraph(entry_cid=entry_cid);
    root ++> g;
    return g;
}

def add_block(graph_root: StoryGraph, cid: str, title: str, content: str) -> Block {
    b = Block(cid=cid, title=title, content=content);
    root ++> b;
    graph_root ++> b;
    return b;
}

def add_choice(src: Block, dst: Block, label: str, edge_id: str) -> bool {
    src +>:Choice(label=label, source_edge_id=edge_id):+> dst;
    return True;
}

def dfs_order(graph_root: StoryGraph, entry_cid: str) -> list[str] {
    target: Block | None = None;
    for b in [graph_root -->][?:Block] {
        if b.cid == entry_cid {
            target = b;
        }
    }
    if target is None {
        empty: list[str] = [];
        return empty;
    }
    blk = target as Block;
    w = blk spawn DfsOrder(claimed={}, order=[]);
    return w.order;
}

def render_markdown(graph_root: StoryGraph, entry_cid: str) -> dict[str, str] {
    target: Block | None = None;
    for b in [graph_root -->][?:Block] {
        if b.cid == entry_cid {
            target = b;
        }
    }
    if target is None {
        empty: dict[str, str] = {};
        return empty;
    }
    blk = target as Block;
    w = blk spawn MdRender(claimed={}, sections={}, order=[]);
    return w.sections;
}

