    if find_package(pkg_id) is not None { return False; }
    pkg = Package(pkg_id=pkg_id, budget_bytes=budget_bytes);
    root ++> pkg;
    return True;
}

def add_part(pkg_id: str, path: str, content_type: str, size: int, compressed_size: int) -> bool {
    pkg = find_package(pkg_id);
    if pkg is None { return False; }
    if pkg.cancelled { return False; }
    # traversal + duplicate + budget guards
    if path.contains("..") or path.startswith("/") or path.startswith("\\") { pkg.evidence.append("traversal:" + path); return False; }
    for q in [pkg ->:Contains:->][?:Part] { if q.path == path { pkg.evidence.append("duplicate:" + path); return False; } }
    if compressed_size > 134217728 { pkg.evidence.append("compressed_limit:" + path); return False; }
    if size > 1048576000 { pkg.evidence.append("expansion_limit:" + path); return False; }
    if content_type == "macro" or path.contains("vbaProject") { pkg.evidence.append("macro:" + path); return False; }
    if path.contains(".exe") or path.contains(".dll") { pkg.evidence.append("executable:" + path); return False; }
    pt = Part(path=path, content_type=content_type, size=size, compressed_size=compressed_size);
    pkg ++> pt :Contains:;
    return True;
}

def add_relationship(src_path: str, rel_id: str, target: str, target_mode: str = "Internal") -> bool {
    src: Part | None = None;
    for p in [root ->:Contains:->][?:Package] {
        for q in [p ->:Contains:->][?:Part] { if q.path == src_path { src = q; } }
    }
    if src is None { return False; }
    if target_mode == "External" {
        # preserve evidence, do not connect
        for pkg in [root ->:Contains:->][?:Package] {
            for q in [pkg ->:Contains:->][?:Part] { if q.path == src_path { pkg.evidence.append("external:" + target); } }
        }
        return False;
    }
    if target.contains("..") { return False; }
    dst: Part | None = None;
    for pkg in [root ->:Contains:->][?:Package] {
        for q in [pkg ->:Contains:->][?:Part] { if q.path == target { dst = q; } }
    }
    if dst is None { return False; }
    s = src as Part;
    d = dst as Part;
    s +>:RelLink(rel_id=rel_id, target_mode=target_mode):+> d;
    return True;
}

def resolve_relationships(start_path: str) -> list[str] {
    start: Part | None = None;
    for pkg in [root ->:Contains:->][?:Package] {
        for k in [pkg ->:Contains:->][?:Part] {
            if k.path == start_path { start = k; }
        }
    }
    if start is None { return []; }
    s = start as Part;
    w = s spawn ResolveWalker(claimed={}, result=[]);
    return w.result;
}

def cancel_package(pkg_id: str) -> bool {
    pkg = find_package(pkg_id);
    if pkg is None { return False; }
    if pkg.cancelled { return False; }
    pkg.cancelled = True;
    # two-phase: collect then disconnect outside walk
    w = pkg spawn DisposeWalker(claimed={});
    parts: list[Part] = [pkg ->:Contains:->][?:Part];
    collected: list[Part] = [];
    for pt in parts { collected.append(pt); }
    for pt in collected { pkg --> pt :Contains:; }
    return True;
}

def get_evidence(pkg_id: str) -> list[str] {
    pkg = find_package(pkg_id);
    if pkg is None { return []; }
    return pkg.evidence;
}

def validate_package(pkg_id: str) -> dict[str, bool] {
    pkg = find_package(pkg_id);
    if pkg is None { return {"valid": False}; }
    has_doc: bool = False;
    for q in [pkg ->:Contains:->][?:Part] { if q.path == "word/document.xml" { has_doc = True; } }
    if has_doc { return {"valid": True}; }
    return {"valid": False};
}

