}

def propagate_health(graph_root: Service) -> dict[str, str] {
    graph_root spawn CycleMark(claimed={});
    w = graph_root spawn TopoCollect(claimed={});
    results: dict[str, str] = {};
    for svc in w.order {
        dep_state = "ok";
        blocked: list[str] = [];
        evidence: list[str] = [];
        for dep in [svc ->:Requires:+>][?:Service] {
            dep_eff = dep.effective_state;
            dep_state = max_state(dep_state, dep_eff);
            ev = dep.sid + ":" + dep_eff + ":required";
            evidence.append(ev);
            if dep_eff != "ok" {
                blocked.append(dep.sid);
            }
        }
        svc.dependency_state = dep_state;
        svc.blocked_by = blocked;
        svc.dependency_evidence = evidence;
        eff = combine_effective(svc.local_state, dep_state);
        if svc.in_cycle {
            eff = max_state(eff, "warn");
        }
        svc.effective_state = eff;
        results[svc.sid] = eff;
    }
    return results;
}

