"""Growth-Circle/cadis#989 - search_files with symlink-safe directory traversal."""

node Dir {
    has cid: str;
    has name: str;
    has is_symlink: bool = False;
}

node File {
    has cid: str;
    has name: str;
    has content: str = "";
}

edge Entry {}

walker SearchWalker {
    has claimed: dict[str, bool] = {};
    has query: str = "";
    has max_results: int = 100;
    has matches: list[str] = [];
    has workspace: str = "";

    can step_dir with Dir entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print("visit", here.cid);
        if not here.cid.startswith(self.workspace) {
            disengage;
        }
        if here.is_symlink {
            disengage;
        }
        files: list = [here ->:Entry:->][?:File];
        for f in files {
            if len(self.matches) >= self.max_results {
                disengage;
            }
            if self.query in f.name or self.query in f.content {
                self.matches.append(f.cid);
            }
        }
        if len(self.matches) >= self.max_results {
            disengage;
        }
        kids: list = [here ->:Entry:->][?:Dir];
        pending: list[Dir] = [];
        for kid in kids {
            pending.append(kid);
        }
        for kid in pending {
            visit :0: [kid];
        }
    }
}

def link_dir(parent: Dir, child: object) -> None {
    parent +>:Entry:+> child;
}

def add_dir(store: dict[str, object], cid: str, name: str, is_symlink: bool = False) -> Dir {
    nd = Dir(cid=cid, name=name, is_symlink=is_symlink);
    store[cid] = nd;
    return nd;
}

def add_file(store: dict[str, object], cid: str, name: str, content: str) -> File {
    nd = File(cid=cid, name=name, content=content);
    store[cid] = nd;
    return nd;
}

def search_files(
    store: dict[str, object],
    workspace: str,
    start_cid: str,
    query: str,
    max_results: int = 100,
) -> list[str] {
    if start_cid not in store {
        return [];
    }
    raw = store[start_cid];
    if not (raw is Dir) {
        return [];
    }
    start = raw as Dir;
    w = start spawn SearchWalker(
        claimed={},
        query=query,
        max_results=max_results,
        matches=[],
        workspace=workspace,
    );
    print("search_done", len(w.matches));
    return w.matches;
}
