```jac
"""Growth-Circle/cadis#989 — search_files safe traversal (symlink cycles + workspace bounds)."""

node PathNode {
    has cid: str;
    has is_dir: bool;
}

edge Child {}
edge Symlink {}

obj SearchStore {
    has by_cid: dict[str, PathNode] = {};
}

walker SearchWalker {
    has workspace_cid: str;
    has query: str;
    has max_results: int;
    has matches: list[str] = [];
    has claimed: dict[str, bool] = {};

    can step with PathNode entry {
        if here.cid in self.claimed { skip; }
        if not in_workspace(self.workspace_cid, here.cid) { disengage; }
        self.claimed[here.cid] = True;
        print("search visit", here.cid);
        if not here.is_dir {
            if query_match(self.query, here.cid) {
                if len(self.matches) < self.max_results {
                    self.matches.append(here.cid);
                }
            }
            disengage;
        }
        kids: list[PathNode] = [];
        for ch in [here ->:Child:->][?:PathNode] { kids.append(ch); }
        for ch in [here ->:Symlink:->][?:PathNode] { kids.append(ch); }
        for kid in kids { visit :0: [kid]; }
        if len(kids) == 0 { disengage; }
    }
}

def in_workspace(ws: str, cid: str) -> bool {
    if cid == ws { return True; }
    prefix = ws + "/";
    return cid.startswith(prefix);
}

def query_match(query: str, cid: str) -> bool {
    return query in cid;
}

def add_path(store: SearchStore, cid: str, is_dir: bool) -> PathNode {
    if cid in store.by_cid { return store.by_cid[cid] as PathNode; }
    nd = PathNode(cid=cid, is_dir=is_dir);
    store.by_cid[cid] = nd;
    return nd;
}

def link_child(parent: PathNode, child: PathNode) -> None {
    parent +>:Child:+> child;
}

def link_symlink(src: PathNode, dst: PathNode) -> None {
    src +>:Symlink:+> dst;
}

def make_search_store(scenario: str) -> SearchStore {
    store = SearchStore();
    if scenario == "outside" {
        ws = add_path(store, "/ws", True);
        ok = add_path(store, "/ws/ok.txt", False);
        esc = add_path(store, "/ws/escape", True);
        out = add_path(store, "/outside", True);
        secret = add_path(store, "/outside/secret.txt", False);
        link_child(ws, ok);
        link_child(ws, esc);
        link_symlink(esc, out);
        link_child(out, secret);
        root ++> ws;
    } elif scenario == "cycle" {
        ws = add_path(store, "/ws", True);
        a = add_path(store, "/ws/a.txt", False);
        loopd = add_path(store, "/ws/loop", True);
        link_child(ws, a);
        link_child(ws, loopd);
        link_symlink(loopd, ws);
        root ++> ws;
    } elif scenario == "diamond" {
        ws = add_path(store, "/ws", True);
        left = add_path(store, "/ws/left", True);
        right = add_path(store, "/ws/right", True);
        join = add_path(store, "/ws/join/target.txt", False);
        link_child(ws, right);
        link_child(ws, left);
        link_child(left, join);
        link_child(right, join);
        root ++> ws;
    } else {
        ws = add_path(store, "/ws", True);
        hit = add_path(store, "/ws/hit.txt", False);
        miss = add_path(store, "/ws/readme.md", False);
        link_child(ws, hit);
        link_child(ws, miss);
        root ++> ws;
    }
    return store;
}

def search_files(workspace: str, start: str, query: str, max_results: int, store: SearchStore) -> list[str] {
    if start not in store.by_cid { return []; }
    start_nd = store.by_cid[start] as PathNode;
    w = start_nd spawn SearchWalker(
        workspace_cid=workspace, query=query, max_results=max_results, matches=[], claimed={}
    );
    out: list[str] = [];
    for m in w.matches { out.append(m); }
    return out;
}

with entry {
    st = make_search_store("outside");
    ws_nd = st.by_cid["/ws"] as PathNode;
    root ++> ws_nd;
    ws_nd spawn SearchWalker(workspace_cid="/ws", query=".txt", max_results=10, matches=[], claimed={});
}
