walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has reached: list[str] = [];

    can step_app with Application entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        kids: list[Finding] = [];
        for f in [here ->:HasFinding:->][?:Finding] {
            if f.fid not in self.reached {
                self.reached.append(f.fid);
            }
            kids.append(f);
        }
        visit :0: kids else { disengage; }
        print(f"reach_app {here.cid} {len(self.reached)}");
    }

    can step_find with Finding entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        if here.fid not in self.reached {
            self.reached.append(here.fid);
        }
        kids: list[Finding] = [];
        for ch in [here ->:Route:->][?:Finding] {
            kids.append(ch);
        }
        visit :0: kids else { disengage; }
        print(f"reach_find {here.fid} {len(self.reached)}");
    }
}

walker RouteWalker {
    has claimed: dict[str, bool] = {};
    has route: list[str] = [];

    can walk with Finding entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        self.route.append(here.fid);
        kids: list[Finding] = [];
        for ch in [here ->:Route:->][?:Finding] {
            kids.append(ch);
        }
        visit :0: kids else { disengage; }
        print(f"route_step {here.fid} {len(self.route)}");
    }
}

def register_application(app_id: str) -> Application {
    nd = Application(cid=app_id);
    root ++> nd;
    return nd;
}

def add_finding(app: Application, fid: str) -> Finding {
    fnd = Finding(fid=fid);
    app +>:HasFinding:+> fnd;
    return fnd;
}

def link_finding_dep(up: Finding, down: Finding) {
    up +>:Route:+> down;
}

def finding_by_id(app: Application, fid: str) -> Finding | None {
    tgt: Finding | None = None;
    for f in [app ->:HasFinding:->][?:Finding] {
        if f.fid == fid {
            tgt = f;
        }
    }
    return tgt;
}

def reachable_finding_ids(app: Application) -> list[str] {
    w = app spawn ReachWalker(claimed={});
    out: list[str] = [];
    for fid in w.reached {
        out.append(fid);
    }
    return sorted(out);
}

def verification_route(start: Finding) -> list[str] {
    w = start spawn RouteWalker(claimed={});
    out: list[str] = [];
    for fid in w.route {
        out.append(fid);
    }
    return out;
}

def verification_route_for_id(app: Application, fid: str) -> list[str] {
    tgt = finding_by_id(app, fid);
    if tgt is None {
        return [];
    }
    return verification_route(tgt);
}
