def build_topology(services: list[dict[str, str]], relations: list[dict[str, str]]) -> GraphRoot {
    graph_root: GraphRoot = GraphRoot();
    nodes: dict[str, Service] = {};
    for s in services {
        sid: str = s["sid"];
        ls: str = s["local_state"];
        ps: str = s["probe_state"];
        stale_val: bool = false;
        if "stale" in s {
            if s["stale"] == "true" { stale_val = true; }
        }
        nd: Service = Service(sid=sid, local_state=ls, probe_state=ps, stale=stale_val);
        nodes[sid] = nd;
        graph_root ++> nd;
    }
    for r in relations {
        src: str = r["src"];
        dst: str = r["dst"];
        strength: str = r["strength"];
        if src in nodes and dst in nodes {
            a: Service | None = nodes[src];
            b: Service | None = nodes[dst];
            if a is not None and b is not None {
                aa: Service = a;
                bb: Service = b;
                if strength == "required" {
                    aa +>:Required:+> bb;
                } else {
                    aa +>:Optional:+> bb;
                }
            }
        }
    }
    return graph_root;
}

def collect_required_dependencies(graph_root: GraphRoot, sid: str) -> list[str] {
    svc: Service | None = find_service(graph_root, sid);
    if svc is None { return []; }
    w = svc spawn CollectRequired(start_sid=sid);
    return w.result;
}

def get_blocked_by(graph_root: GraphRoot, sid: str) -> list[str] {
    reqs: list[str] = collect_required_dependencies(graph_root, sid);
    out: list[str] = [];
    for rid in reqs {
        rs: Service | None = find_service(graph_root, rid);
        if rs is None {
            out.append(rid);
        } else {
            r: Service = rs;
            if r.stale { out.append(rid); }
            else {
                if r.local_state != "RUNNING" and r.local_state != "healthy" {
                    out.append(rid);
                }
            }
        }
    }
    return out;
}

def get_dependency_evidence(graph_root: GraphRoot, sid: str) -> list[dict[str, str]] {
    reqs: list[str] = collect_required_dependencies(graph_root, sid);
    out: list[dict[str, str]] = [];
    for rid in reqs {
        d: dict[str, str] = {};
        d["target"] = rid;
        d["rel_type"] = "required";
        rs: Service | None = find_service(graph_root, rid);
        if rs is None {
            d["target_state"] = "unknown";
            d["stale"] = "true";
        } else {
            r: Service = rs;
            d["target_state"] = r.local_state;
            if r.stale { d["stale"] = "true"; } else { d["stale"] = "false"; }
        }
        out.append(d);
    }
    return out;
}

def get_effective_state(graph_root: GraphRoot, sid: str) -> str {
    svc: Service | None = find_service(graph_root, sid);
    if svc is None { return "unknown"; }
    s: Service = svc;
    if s.local_state == "fail" { return "fail"; }
    if s.local_state == "STOPPED" { return "fail"; }
    if s.stale { return "unknown"; }
    reqs: list[str] = collect_required_dependencies(graph_root, sid);
    has_unknown: bool = false;
    blocked: bool = false;
    for rid in reqs {
        rs: Service | None = find_service(graph_root, rid);
        if rs is None { has_unknown = true; }
        else {
            r: Service = rs;
            if r.stale { has_unknown = true; }
            else {
                if r.local_state == "fail" { blocked = true; }
                else {
                    if r.local_state == "STOPPED" { blocked = true; }
                    else {
                        if r.local_state == "unknown" { has_unknown = true; }
                    }
                }
            }
        }
    }
    if has_unknown {
        if s.probe_state == "fail" { return "fail"; }
        return "degraded";
    }
    if blocked {
        if s.probe_state == "fail" { return "fail"; }
        return "degraded";
    }
    return s.local_state;
}

def get_health_view(graph_root: GraphRoot, sid: str) -> dict[str, str] {
