"""Build dependency graph analysis — TheLarkInn/aipm#1796."""

node CrateUnit {
    has unit_id: str;
    has name: str;
    has version: str;
    has duration_secs: int = 0;
    has default_features: list[str] = [];
}

edge Depends {}

obj BuildStore {
    has units: dict[str, CrateUnit] = {};
}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with CrateUnit entry {
        if here.unit_id in self.claimed { skip; }
        self.claimed[here.unit_id] = True;
        self.found.append(here.unit_id);
        print("reach", here.unit_id);
        kids: list[CrateUnit] = [];
        for dep in [here ->:Depends:->][?:CrateUnit] {
            kids.append(dep);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def make_store() -> BuildStore {
    return BuildStore();
}

def add_unit(
    store: BuildStore,
    unit_id: str,
    name: str,
    version: str,
    duration_secs: int,
    default_features: list[str] | None = None,
) -> None {
    feats: list[str] = [];
    if default_features is not None {
        for f in default_features {
            feats.append(f);
        }
    }
    nd = CrateUnit(
        unit_id=unit_id,
        name=name,
        version=version,
        duration_secs=duration_secs,
        default_features=feats,
    );
    store.units[unit_id] = nd;
    root ++> nd;
}

def add_dep(store: BuildStore, from_id: str, to_id: str) -> None {
    if from_id not in store.units { return; }
    if to_id not in store.units { return; }
    frm = store.units[from_id] as CrateUnit;
    to = store.units[to_id] as CrateUnit;
    frm +>:Depends:+> to;
}

def duplicate_names(store: BuildStore) -> list[str] {
    counts: dict[str, int] = {};
    for uid in sorted(store.units.keys()) {
        u = store.units[uid] as CrateUnit;
        nm = u.name;
        if nm in counts {
            counts[nm] = counts[nm] + 1;
        } else {
            counts[nm] = 1;
        }
    }
    out: list[str] = [];
    for nm in sorted(counts.keys()) {
        if counts[nm] >= 2 {
            out.append(nm);
        }
    }
    return out;
}

def _cp_down(here: CrateUnit) -> int {
    total: int = here.duration_secs;
    deps: list[CrateUnit] = [];
    for dep in [here ->:Depends:->][?:CrateUnit] {
        deps.append(dep);
    }
    if len(deps) == 0 {
        return total;
    }
    best_child: int = 0;
    for dep in deps {
        cand = _cp_down(dep);
        if cand > best_child {
            best_child = cand;
        }
    }
    return total + best_child;
}

def critical_path_secs(store: BuildStore, target_id: str) -> int {
    if target_id not in store.units {
        return 0;
    }
    tgt = store.units[target_id] as CrateUnit;
    return _cp_down(tgt);
}

def reachable_units(store: BuildStore, start_id: str) -> list[str] {
    if start_id not in store.units {
        return [];
    }
    start = store.units[start_id] as CrateUnit;
    w = start spawn ReachWalker(claimed={});
    out: list[str] = [];
    for uid in w.found {
        out.append(uid);
    }
    out.sort();
    return out;
}

def trimmable_features(
    store: BuildStore,
    unit_id: str,
    keep: list[str],
) -> list[str] {
    if unit_id not in store.units {
        return [];
    }
    u = store.units[unit_id] as CrateUnit;
    keep_set: dict[str, bool] = {};
    for f in keep {
        keep_set[f] = True;
    }
    out: list[str] = [];
    for f in u.default_features {
        if f not in keep_set {
            out.append(f);
        }
    }
    out.sort();
    return out;
}
