"""Blob reconstruction interruption-safe supervisor — locke1979/OpenNICF#111."""

node Blob {
  has blob_id: str;
  has size: int = 0;
  has git_sha: str = "";
  has status: str = "pending";
}

node Supervisor {
  has session_id: str;
  has alive: bool = True;
  has checkpoint: int = 0;
}

