        visit :0: nxt else { disengage; }
    }
}

def build_graph(vids: list[str], pairs: list[list[str]]) -> GraphRoot {
    gr: GraphRoot = GraphRoot(gid="root");
    mp: dict[str, Vertex] = {};
    for vid in vids {
        nd: Vertex = Vertex(vid=vid);
        mp[vid] = nd;
        gr +>:Contains:+> nd;
    }
    for p in pairs {
        if len(p) < 2 { continue; }
        s: str = p[0];
        t: str = p[1];
        if s not in mp { continue; }
        if t not in mp { continue; }
        sv: Vertex = mp[s];
        tv: Vertex = mp[t];
        sv +>:Dep:+> tv;
    }
    return gr;
}

def kahn_topological_sort(vids: list[str], pairs: list[list[str]]) -> list[str] {
    gr: GraphRoot = build_graph(vids, pairs);
    mp2: dict[str, Vertex] = {};
    for nd in [gr ->:Contains:->][?:Vertex] { mp2[nd.vid] = nd; }
    indeg: dict[str, int] = {};
    for vid in vids { indeg[vid] = 0; }
    for v in [gr ->:Contains:->][?:Vertex] {
        for nb in [v ->:Dep:->][?:Vertex] { indeg[nb.vid] = indeg[nb.vid] + 1; }
    }
    zero_vids: list[str] = [];
    for vid in vids { if indeg[vid] == 0 { zero_vids.append(vid); } }
    zero_vids = sorted(zero_vids);
    queue: list[Vertex] = [];
    for zv in zero_vids { if zv in mp2 { queue.append(mp2[zv]); } }
    order: list[str] = [];
    idx: int = 0;
    while idx < len(queue) {
        cur: Vertex = queue[idx];
        idx = idx + 1;
        order.append(cur.vid);
        nbrs: list[Vertex] = [cur ->:Dep:->][?:Vertex];
        nbr_ids: list[str] = [];
        for nb in nbrs { nbr_ids.append(nb.vid); }
        nbr_ids = sorted(nbr_ids);
        for nid in nbr_ids {
            indeg[nid] = indeg[nid] - 1;
            if indeg[nid] == 0 { if nid in mp2 { queue.append(mp2[nid]); } }
        }
    }
    if len(order) != len(vids) { raise Exception("cycle detected: graph has at least one cycle"); }
    return order;
}

