def find_enum(graph_root: GraphRoot, name: str) -> EnumDef | None {
    # scan declares edges without building adjacency dict
    all: list[EnumDef] = [graph_root ->:Declares:->][?:EnumDef];
    for nd in all {
        if nd.eid == name {
            return nd;
        }
    }
    return None;
}

def define_enum(graph_root: GraphRoot, name: str, refs: list[str]) -> EnumDef {
    nd: EnumDef = EnumDef(eid=name, ename=name, refs=refs);
    graph_root +>:Declares:+> nd;
    for r in refs {
        tgt: EnumDef | None = find_enum(graph_root, r);
        if tgt is not None {
            # avoid self-loop duplicate
            already: bool = False;
            for ex in [nd ->:Ref:->][?:EnumDef] {
                if ex.eid == r { already = True; }
            }
            if already == False {
                nd +>:Ref:+> tgt;
            }
        }
    }
    # link pending predecessors that were waiting for this name
    all: list[EnumDef] = [graph_root ->:Declares:->][?:EnumDef];
    for other in all {
        if other.eid == name { continue; }
        need: bool = False;
        for rr in other.refs {
            if rr == name { need = True; }
        }
        if need {
            has_edge: bool = False;
            for ex in [other ->:Ref:->][?:EnumDef] {
                if ex.eid == name { has_edge = True; }
            }
            if has_edge == False {
                other +>:Ref:+> nd;
            }
        }
    }
    return nd;
}

def printers_ordered(graph_root: GraphRoot) -> list[str] {
    # topological-sort-or-refuse for printer defs; clean refusal is []
    all: list[EnumDef] = [graph_root ->:Declares:->][?:EnumDef];
    if len(all) == 0 {
        return [];
    }
    remaining: dict[str, int] = {};
    for n in all {
        deps: list[EnumDef] = [n ->:Ref:->][?:EnumDef];
        remaining[n.eid] = len(deps);
    }
    q: list[EnumDef] = [];
    for n in all {
        if remaining[n.eid] == 0 {
            q.append(n);
        }
    }
    ordered: list[str] = [];
    while len(q) > 0 {
        # deterministic min-eid extraction, no sorting assumption
        smallest: EnumDef = q[0];
        smallest_idx: int = 0;
        idx: int = 0;
        for cand in q {
            if cand.eid < smallest.eid {
                smallest = cand;
                smallest_idx = idx;
            }
            idx = idx + 1;
        }
        new_q: list[EnumDef] = [];
        idx2: int = 0;
        for cand in q {
            if idx2 != smallest_idx {
                new_q.append(cand);
            }
            idx2 = idx2 + 1;
        }
        q = new_q;
        cur: EnumDef = smallest;
        ordered.append(cur.eid);
        # decrement predecessors that depend on cur
        for pred in all {
            for dep in [pred ->:Ref:->][?:EnumDef] {
                if dep.eid == cur.eid {
                    remaining[pred.eid] = remaining[pred.eid] - 1;
                    if remaining[pred.eid] == 0 {
                        q.append(pred);
                    }
                }
            }
        }
    }
    if len(ordered) != len(all) {
        print("cycle detected clean refusal");
        return [];
    }
    return ordered;
}

def has_cycle(graph_root: GraphRoot) -> bool {
    all: list[EnumDef] = [graph_root ->:Declares:->][?:EnumDef];
    if len(all) == 0 { return False; }
    ord: list[str] = printers_ordered(graph_root);
    if len(ord) == 0 { return True; }
    return False;
}

