        self.claimed[here.blob_id] = True;
        if here.status == "pending" { self.result.append(here.blob_id); }
        for nxt in [here ->:Depends:->][?:Blob] { visit :0: [nxt]; }
        print(here.blob_id);
    }
}
walker DescendantWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has nodes: list[Proc] = [];
    can walk_sess with Session entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        for ch in [here ->:Spawned:->][?:Proc] { visit :0: [ch]; }
        print(here.sid);
    }
