"""Derived-state currentness, expiring authorization, dependency topology — markgoodbody-bit/COM#56."""

node Artifact {
    has cid: str;
    has head: str = "";
    has not_after_utc: str | None = None;
}

edge Depends {}

walker ClosureWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step with Artifact entry {
        print("closure", here.cid);
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        kids: list[Artifact] = [];
        for ch in [here ->:Depends:->][?:Artifact] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has reached: bool = False;

    can step with Artifact entry {
        print("reach", here.cid, self.target);
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.cid == self.target {
            self.reached = True;
            disengage;
        }
        kids: list[Artifact] = [];
        for ch in [here ->:Depends:->][?:Artifact] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

walker AuditWalker {
    has claimed: dict[str, bool] = {};

    can step with Artifact entry {
        print("audit", here.cid, here.head, here.not_after_utc);
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        kids: list[Artifact] = [];
        for ch in [here ->:Depends:->][?:Artifact] {
            kids.append(ch);
        }
        visit :0: kids else {
            disengage;
        }
    }
}

def _node_index(nodes: list[Artifact]) -> dict[str, Artifact] {
    out: dict[str, Artifact] = {};
    for nd in nodes {
        out[nd.cid] = nd;
    }
    return out;
}

def build_graph(edges: list[tuple[str, str]]) -> dict[str, list[str]] {
    graph: dict[str, list[str]] = {};
    for pair in edges {
        src = pair[0];
        dst = pair[1];
        if src not in graph {
            graph[src] = [];
        }
        graph[src].append(dst);
        if dst not in graph {
            graph[dst] = [];
        }
    }
    return graph;
}

def materialize_graph(
    edges: list[tuple[str, str]],
    heads: dict[str, str],
    expiries: dict[str, str] | None = None,
) -> list[Artifact] {
    exp: dict[str, str] = {};
    if expiries is not None {
        for k in expiries {
            exp[k] = expiries[k];
        }
    }
    ids: dict[str, bool] = {};
    for pair in edges {
        ids[pair[0]] = True;
        ids[pair[1]] = True;
    }
    for k in heads {
        ids[k] = True;
    }
    for k in exp {
        ids[k] = True;
    }
    nodes: list[Artifact] = [];
    for cid in sorted(ids) {
        hd = "";
        if cid in heads {
            hd = heads[cid];
        }
        na: str | None = None;
        if cid in exp {
            na = exp[cid];
        }
        nd = Artifact(cid=cid, head=hd, not_after_utc=na);
        root ++> nd;
        nodes.append(nd);
    }
    by_id = _node_index(nodes);
    for pair in edges {
        a = by_id[pair[0]];
        b = by_id[pair[1]];
        a +>:Depends:+> b;
    }
    return nodes;
}

def _graph_has_node(graph: dict[str, list[str]], cid: str) -> bool {
    if cid in graph {
        return True;
    }
    for src in graph {
        for dst in graph[src] {
            if dst == cid {
                return True;
            }
        }
    }
    return False;
}

def _spawn_root(edges: list[tuple[str, str]], heads: dict[str, str]) -> dict[str, Artifact] {
    nodes = materialize_graph(edges, heads, None);
    return _node_index(nodes);
}

def dependency_closure(root_cid: str, graph: dict[str, list[str]]) -> list[str] {
    if not _graph_has_node(graph, root_cid) {
        return [];
    }
    edges: list[tuple[str, str]] = [];
    for src in sorted(graph) {
        for dst in graph[src] {
            edges.append((src, dst));
        }
    }
    heads: dict[str, str] = {};
    by_id = _spawn_root(edges, heads);
    if root_cid not in by_id {
        return [];
    }
    w = by_id[root_cid] spawn ClosureWalker();
    return sorted(w.found);
}

def path_reachable(
    src_cid: str,
    dst_cid: str,
    graph: dict[str, list[str]],
) -> bool {
    if not _graph_has_node(graph, src_cid) {
        return False;
    }
    if not _graph_has_node(graph, dst_cid) {
        return False;
    }
    edges: list[tuple[str, str]] = [];
    for s in sorted(graph) {
        for d in graph[s] {
            edges.append((s, d));
        }
    }
    heads: dict[str, str] = {};
    by_id = _spawn_root(edges, heads);
    if src_cid not in by_id {
        return False;
    }
    w = by_id[src_cid] spawn ReachWalker(target=dst_cid);
    return w.reached;
}

def stale_head_ids(
    recorded: dict[str, str],
    current: dict[str, str],
) -> list[str] {
    stale: list[str] = [];
    for cid in sorted(recorded) {
        if cid not in current {
            stale.append(cid);
        } elif recorded[cid] != current[cid] {
            stale.append(cid);
        }
    }
    return stale;
}

def request_still_valid(not_after_utc: str | None, now_utc: str) -> bool {
    if not_after_utc is None {
        return True;
    }
    return now_utc <= not_after_utc;
}

def queued_authorization(
    cid: str,
    nodes: dict[str, Artifact],
    fallback_exp: dict[str, str] | None,
    now_utc: str,
) -> bool {
    exp: dict[str, str] = {};
    if fallback_exp is not None {
        for k in fallback_exp {
            exp[k] = fallback_exp[k];
        }
    }
    na: str | None = None;
    if cid in nodes {
        na = nodes[cid].not_after_utc;
    } elif cid in exp {
        na = exp[cid];
    }
    return request_still_valid(na, now_utc);
}

