"""Synthetic forward-flow assignment model for openrewrite/rewrite-analysis#113.

Mutual arg<->select recursion without a visited guard overflows; claim-map
walk collects a finite assignment closure instead.
"""

node FlowNode {
    has cid: str;
    has kind: str;
    has method: str = "";
    has idx: int = -1;
}

edge Flow {}
edge ArgToSelect {}
edge SelectToArg {}

node FlowGraph {
    has nodes: dict[str, FlowNode] = {};
}

walker AssignWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can walk with FlowNode entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        kids: list[FlowNode] = [];
        for ch in [here ->:Flow:->][?:FlowNode] {
            kids.append(ch);
        }
        for ch in [here ->:ArgToSelect:->][?:FlowNode] {
            kids.append(ch);
        }
        for ch in [here ->:SelectToArg:->][?:FlowNode] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
        print({"visit": here.cid, "found": self.found});
    }
}

def build_forward_flow(node_rows: list[dict], edge_rows: list[dict]) -> FlowGraph {
    g = FlowGraph();
    for row in node_rows {
        nid = row["id"] as str;
        kind = row["kind"] as str;
        method = "";
        if "method" in row {
            method = row["method"] as str;
        }
        idx = -1;
        if "idx" in row {
            idx = row["idx"] as int;
        }
        nd = FlowNode(cid=nid, kind=kind, method=method, idx=idx);
        g.nodes[nid] = nd;
        root ++> nd;
    }
    for erow in edge_rows {
        src_id = erow["src"] as str;
        dst_id = erow["dst"] as str;
        if src_id not in g.nodes or dst_id not in g.nodes {
            continue;
        }
        src = g.nodes[src_id];
        dst = g.nodes[dst_id];
        ek = erow["kind"] as str;
        if ek == "flow" {
            src +>:Flow:+> dst;
        } elif ek == "arg_to_select" {
            src +>:ArgToSelect:+> dst;
        } elif ek == "select_to_arg" {
            src +>:SelectToArg:+> dst;
        }
    }
    return g;
}

def compute_variable_assignment(g: FlowGraph, node_id: str) -> list[str] {
    if node_id not in g.nodes {
        return [];
    }
    start = g.nodes[node_id];
    w = start spawn AssignWalker(claimed={}, found=[]);
    out: list[str] = [];
    for x in w.found {
        out.append(x);
    }
    out.sort();
    return out;
}

def is_mutual_flow_pair(g: FlowGraph, arg_id: str, select_id: str) -> bool {
    if arg_id not in g.nodes or select_id not in g.nodes {
        return False;
    }
    arg = g.nodes[arg_id];
    sel = g.nodes[select_id];
    a2s = False;
    for _ in [arg ->:ArgToSelect:-> sel][?:FlowNode] {
        a2s = True;
    }
    s2a = False;
    for _ in [sel ->:SelectToArg:-> arg][?:FlowNode] {
        s2a = True;
    }
    return a2s and s2a;
}
