            self.cache[cache_key] = target;
            self.resolved[here.name] = target;
            print("resolve ", here.name, " -> ", target);
        }
        links: list[Importer] = [here ->:ImpLink:->][?:Importer];
        if len(links) > 0 {
            for nxt in links {
