def seed_discovery_graph() -> Dir {
    d_repo = Dir(path="/repo", manifest=False);
    root ++> d_repo;
    d_a = Dir(path="/repo/a", manifest=False);
    d_b = Dir(path="/repo/b", manifest=False);
    d_web = Dir(path="/repo/apps/web", manifest=True);
    d_repo +>:Child:+> d_a;
    d_repo +>:Child:+> d_b;
    d_a +>:Child:+> d_web;
