"""xurble/django-feed-reader#48 — subscription parent validation and safe traversal."""

node Subscription {
    has nid: str;
    has uid: str;
    has is_folder: bool = False;
    has unread: int = 0;
}

edge ParentOf {}

def sub_from_dict(rec: dict) -> Subscription {
    is_folder_val: bool = False;
    if "is_folder" in rec {
        is_folder_val = rec["is_folder"];
    }
    unread_val: int = 0;
    if "unread" in rec {
        unread_val = rec["unread"];
    }
    return Subscription(
        nid=rec["nid"],
        uid=rec["uid"],
        is_folder=is_folder_val,
        unread=unread_val
    );
}

def materialize(store: dict) -> dict[str, Subscription] {
    nodes: dict[str, Subscription] = {};
    for key in sorted(store.keys()) {
        rec = store[key];
        nd = sub_from_dict(rec);
        nodes[nd.nid] = nd;
    }
    for key in sorted(store.keys()) {
        rec = store[key];
        child = nodes[rec["nid"]];
        if "parent_ids" in rec {
            pids = rec["parent_ids"];
            for i in range(len(pids)) {
                pid = pids[i];
                if pid in nodes {
                    parent = nodes[pid];
                    parent +>:ParentOf:+> child;
                }
            }
        } elif "parent_id" in rec {
            pid = rec["parent_id"];
            if pid {
                if pid in nodes {
                    parent = nodes[pid];
                    parent +>:ParentOf:+> child;
                }
            }
        }
    }
    return nodes;
}

walker CycleProbe {
    has claimed: dict[str, bool] = {};
    has stop_at: str = "";
    has found: bool = False;

    can ascend with Subscription entry {
        print("cycle_probe", here.nid);
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        if here.nid == self.stop_at {
            self.found = True;
            disengage;
        }
        ups: list[Subscription] = [];
        for p in [<-:ParentOf:<-][?:Subscription] {
            ups.append(p);
        }
        if ups {
            visit ups;
        } else {
            disengage;
        }
    }
}

def would_create_cycle(child_id: str, parent_id: str, store: dict) -> bool {
    nodes = materialize(store);
    if child_id not in nodes {
        return False;
    }
    if parent_id not in nodes {
        return False;
    }
    start = nodes[parent_id];
    w = start spawn CycleProbe(claimed={}, stop_at=child_id, found=False);
    print("would_cycle", w.found);
    return w.found;
}

def validate_parent(child_id: str, parent_id: str, store: dict) -> dict {
    result: dict = {"ok": False, "reason": ""};
    nodes = materialize(store);
    if child_id not in nodes {
        result["reason"] = "unknown_child";
        return result;
    }
    if parent_id not in nodes {
        result["reason"] = "unknown_parent";
        return result;
    }
    if child_id == parent_id {
        result["reason"] = "self_parent";
        return result;
    }
    child = nodes[child_id];
    parent = nodes[parent_id];
    if not parent.is_folder {
        result["reason"] = "non_folder_parent";
        return result;
    }
    if child.uid != parent.uid {
        result["reason"] = "cross_user";
        return result;
    }
    if would_create_cycle(child_id, parent_id, store) {
        result["reason"] = "cycle";
        return result;
    }
    result["ok"] = True;
    result["reason"] = "";
    return result;
}

walker DescendCollect {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    has origin: str = "";

    can step_down with Subscription entry {
        print("descend", here.nid);
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        if here.nid != self.origin {
            self.found.append(here.nid);
        }
        kids: list[Subscription] = [];
        for ch in [here ->:ParentOf:->][?:Subscription] {
            kids.append(ch);
        }
        if kids {
            visit :0: kids;
        } else {
            disengage;
        }
    }
}

def collect_descendant_ids(root_id: str, store: dict) -> list[str] {
    nodes = materialize(store);
    if root_id not in nodes {
        empty: list[str] = [];
        return empty;
    }
    start = nodes[root_id];
    w = start spawn DescendCollect(claimed={}, found=[], origin=root_id);
    out = w.found;
    out.sort();
    return out;
}

walker UnreadSum {
    has claimed: dict[str, bool] = {};
    has total: int = 0;

    can sum_sub with Subscription entry {
        print("unread_sum", here.nid, here.unread);
        if here.nid in self.claimed {
            skip;
        }
        self.claimed[here.nid] = True;
        self.total = self.total + here.unread;
        kids: list[Subscription] = [];
        for ch in [here ->:ParentOf:->][?:Subscription] {
            kids.append(ch);
        }
        if kids {
            visit kids;
        } else {
            disengage;
        }
    }
}

def unread_count_aggregate(root_id: str, store: dict) -> int {
    nodes = materialize(store);
    if root_id not in nodes {
        return 0;
    }
    start = nodes[root_id];
    w = start spawn UnreadSum(claimed={}, total=0);
    return w.total;
}

def unread_subscription_ids_for_user(user_id: str, store: dict) -> list[str] {
    ids: list[str] = [];
    for key in sorted(store.keys()) {
        rec = store[key];
        if rec["uid"] != user_id {
            continue;
        }
        unread_val: int = 0;
        if "unread" in rec {
            unread_val = rec["unread"];
        }
        if unread_val > 0 {
            ids.append(rec["nid"]);
        }
    }
    ids.sort();
    return ids;
}
