    if pid not in repo.projects { return []; }
    p: Project = repo.projects[pid] as Project;
    kids: list[Project] = [p ->:Depends:->][?:Project];
    out: list[str] = [];
    for k in kids {
        out.append(k.pid);
    }
    return out;
}

