def create_qualification_graph(lane_key: str, sha: str) -> QualGraph {
    g = QualGraph(lane_key=lane_key, sha=sha);
    root ++> g;
    return g;
}

def add_matrix_row(graph_root: QualGraph, row_id: str, status: str) -> MatrixRow {
    r = MatrixRow(row_id=row_id, status=status);
    graph_root +>:Contains:+> r;
    return r;
}

def add_prereq(graph_root: QualGraph, pid: str, kind: str, satisfied: bool) -> Prereq {
    p = Prereq(pid=pid, kind=kind, satisfied=satisfied);
    graph_root +>:Contains:+> p;
    return p;
}

def add_dependency(src: MatrixRow, dst: MatrixRow) -> None {
    src +>:Depends:+> dst;
}

def attach_prereq(row: MatrixRow, pr: Prereq) -> None {
    row +>:Requires:+> pr;
}

def get_closure_rows(start: MatrixRow) -> list[str] {
    w = start spawn ClosureWalker(claimed={}, found=[]);
    ids: list[str] = [];
    for r in w.found { ids.append(r.row_id); }
    return sorted(ids);
}

def get_closure_missing(start: MatrixRow) -> list[str] {
    w = start spawn MissingWalker(claimed={}, missing=[]);
    return sorted(w.missing);
}

def get_missing_prereqs(graph_root: QualGraph) -> list[str] {
    out: list[str] = [];
    for p in [graph_root ->:Contains:->][?:Prereq] {
        if p.satisfied == False { out.append(p.pid); }
    }
    return sorted(out);
}

def is_local_pass(graph_root: QualGraph) -> bool {
    rows: list[MatrixRow] = [];
    for r in [graph_root ->:Contains:->][?:MatrixRow] { rows.append(r); }
    if len(rows) != 21 { return False; }
    for r in rows {
        if r.status != "PASS" { return False; }
    }
    for p in [graph_root ->:Contains:->][?:Prereq] {
        if p.satisfied == False { return False; }
    }
    return True;
}

