    return {"mutationId": g.gname + "#" + str(g.mutation)};
}

def upsert_edges(g: GraphStore, edges: list[dict[str, str]]) -> dict[str, str] {
    # reject missing endpoints without partial writes
    for rec in edges {
        if find_node(g, rec["from"]) is None { return {"mutationId": ""}; }
        if find_node(g, rec["to"]) is None { return {"mutationId": ""}; }
    }
    for rec in edges {
