def shortest_path(g: GraphStore, from_id: str, to_id: str, direction: str) -> list[str] | None {
    src: GraphNode | None = find_node(g, from_id);
    if src is None { return None; }
    if find_node(g, to_id) is None { return None; }
    w = src spawn ShortestCollect(target=to_id);
    if len(w.found) == 0 { return None; }
    # reverse to source->target order
    out: list[str] = [];
    i: int = len(w.found) - 1;
    while i >= 0 { out.append(w.found[i]); i -= 1; }
    return out;
}

