def upsert_nodes(g: GraphStore, items: list[dict[str, str]]) -> dict[str, int] {
    for it in items {
        nid: str = it["id"];
        k: str = it["kind"];
        nd = find_node(g, nid);
        if nd is not None {
            nd.kind = k;
        } else {
            nd2 = GraphNode(nid=nid, kind=k);
            g +>:StoreLink:+> nd2;
        }
    }
    g.mutation += 1;
    return {"mutationId": g.mutation};
}

def upsert_edges(g: GraphStore, items: list[dict[str, str]]) -> dict[str, int] {
    for it in items {
        f: str = it["from"];
        t: str = it["to"];
        if find_node(g, f) is None { return {"mutationId": g.mutation}; }
        if find_node(g, t) is None { return {"mutationId": g.mutation}; }
    }
    for it in items {
        eid: str = it["id"];
        k: str = it["kind"];
        fn = find_node(g, it["from"]);
        tn = find_node(g, it["to"]);
        if fn is not None and tn is not None {
            fn +>:GraphEdge(eid=eid, kind=k):+> tn;
            g.edge_ids[eid] = True;
        }
    }
    g.mutation += 1;
    return {"mutationId": g.mutation};
}

def get_nodes(g: GraphStore, ids: list[str]) -> list[dict[str, str]] {
    res: list[dict[str, str]] = [];
    for nid in ids {
        nd = find_node(g, nid);
        if nd is not None {
            d: dict[str, str] = {};
            d["id"] = nd.nid;
            d["kind"] = nd.kind;
            res.append(d);
        }
    }
    return res;
}

def get_edges(g: GraphStore, ids: list[str]) -> list[dict[str, str]] {
