```jac
node ServiceNode {
    has sid: str;
    has local_state: str;
    has app_probe_failed: bool = False;
    has stale: bool = False;
}
node GraphRoot {
    has registry: dict[str, ServiceNode] = {};
}
edge RequiredDep {}
edge OptionalDep {}

walker CollectRequired {
    has claimed: dict[str, bool] = {};
    has blocked_by: list[str] = [];
    has evidence: list[dict[str, str]] = [];
    has found: list[ServiceNode] = [];

    can start with entry {
        print("collect start");
        disengage;
    }
    can step with ServiceNode entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        print(here.sid);
        self.found.append(here);
        kids: list[ServiceNode] = [here ->:RequiredDep:->];
        for kid in kids {
            ev: dict[str, str] = {"target": kid.sid, "state": kid.local_state, "relation": "required"};
            self.evidence.append(ev);
        }
        visit kids else { disengage; }
    }
}

def new_topology() -> GraphRoot {
    g: GraphRoot = GraphRoot(registry={});
    root ++> g;
    return g;
}

def register_service(graph_root: GraphRoot, sid: str, local_state: str, app_failed: bool, stale: bool) -> ServiceNode {
    reg: dict[str, ServiceNode] = graph_root.registry;
    if sid in reg {
        nd: ServiceNode = reg[sid];
        nd.local_state = local_state;
        nd.app_probe_failed = app_failed;
        nd.stale = stale;
        return nd;
    }
    nd: ServiceNode = ServiceNode(sid=sid, local_state=local_state, app_probe_failed=app_failed, stale=stale);
    graph_root.registry[sid] = nd;
    graph_root ++> nd;
    root ++> nd;
    return nd;
}

def link_required(graph_root: GraphRoot, src: str, dst: str) -> bool {
    reg: dict[str, ServiceNode] = graph_root.registry;
    if src not in reg { return False; }
    if dst not in reg { return False; }
    src_nd: ServiceNode = reg[src];
    dst_nd: ServiceNode = reg[dst];
    src_nd +>:RequiredDep:+> dst_nd;
    return True;
}

def link_optional(graph_root: GraphRoot, src: str, dst: str) -> bool {
    reg: dict[str, ServiceNode] = graph_root.registry;
    if src not in reg { return False; }
    if dst not in reg { return False; }
    src_nd: ServiceNode = reg[src];
    dst_nd: ServiceNode = reg[dst];
    src_nd +>:OptionalDep:+> dst_nd;
    return True;
}

def health_payload(graph_root: GraphRoot, sid: str) -> dict {
    reg: dict[str, ServiceNode] = graph_root.registry;
    if sid not in reg {
        out: dict = {};
        out["local_state"] = "unknown";
        out["dependency_state"] = "unknown";
        out["effective_state"] = "unknown";
        out["required_dependencies"] = [];
        out["blocked_by"] = [];
        out["dependency_evidence"] = [];
        out["stale"] = False;
        return out;
    }
    src: ServiceNode = reg[sid];
    w: CollectRequired = src spawn CollectRequired(claimed={}, blocked_by=[], evidence=[], found=[]);
    states: dict[str, str] = {};
    for nd in w.found {
        states[nd.sid] = nd.local_state;
    }
    # two-phase fixpoint to propagate required deps without recursion
    changed: bool = True;
    it: int = 0;
    while changed {
        if it > 20 { break; }
        changed = False;
        it += 1;
        for nd in w.found {
            cur: str = states[nd.sid];
            eff: str = cur;
            if nd.app_probe_failed {
                eff = "fail";
            } else {
                if nd.local_state == "fail" {
                    eff = "fail";
                } else {
                    if nd.stale {
                        eff = "degraded";
                    } else {
                        deps: list[ServiceNode] = [nd ->:RequiredDep:->];
                        dep_failed: bool = False;
                        dep_unknown: bool = False;
                        for d in deps {
                            if d.sid not in states {
                                dep_unknown = True;
                            } else {
                                ds: str = states[d.sid];
                                if ds == "fail" { dep_failed = True; }
                                else { if ds == "degraded" { dep_failed = True; } else { if ds == "unknown" { dep_unknown = True; } } }
                                if d.stale { dep_unknown = True; }
                            }
                        }
                        if dep_unknown { eff = "degraded"; }
                        else { if dep_failed { eff = "degraded"; } else { eff = cur; } }
                        if nd.local_state == "fail" and dep_failed {
                            eff = "fail";
                        }
                    }
                }
            }
            if eff != cur {
                states[nd.sid] = eff;
                changed = True;
            }
        }
    }
    direct: list[ServiceNode] = [src ->:RequiredDep:->];
    required: list[str] = [];
    for d in direct { required.append(d.sid); }
    blocked: list[str] = [];
    for d in direct {
        ds: str = states[d.sid];
        if d.stale { blocked.append(d.sid); }
        else { if ds == "fail" { blocked.append(d.sid); } else { if ds == "degraded" { blocked.append(d.sid); } else { if ds == "unknown" { blocked.append(d.sid); } } } }
    }
    dep_state: str = "healthy";
    if len(blocked) > 0 { dep_state = "degraded"; }
    # also check stale evidence among transitive deps for dependency_state
    for nd in w.found {
        if nd.sid != sid and nd.stale { dep_state = "degraded"; }
    }
    payload: dict = {};
    payload["local_state"] = src.local_state;
    payload["dependency_state"] = dep_state;
    payload["effective_state"] = states[src.sid];
    payload["required_dependencies"] = required;
    payload["blocked_by"] = blocked;
    payload["dependency_evidence"] = w.evidence;
    payload["stale"] = src.stale;
    return payload;
}

