    can traverse with Evidence entry {
        if here.evid_id in self.claimed { skip; }
        self.claimed[here.evid_id] = True;
        self.found.append(here.evid_id);
        print(here.evid_id);
        for nxt in [here ->:Reference:->][?:Evidence] {
            visit :0: [nxt];
        }
