}

walker ReachWalker {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];
    can start with App entry {
        if here.app_id in self.claimed { skip; }
        self.claimed[here.app_id] = True;
        print(here.app_id);
        for nxt in [here ->:Contains:->][?:Evidence] {
            visit :0: [nxt];
        }
    }
    can follow with Evidence entry {
        if here.evid_id in self.claimed { skip; }
        self.claimed[here.evid_id] = True;
