def create_workbench() -> Workbench {
    wb = Workbench();
    root ++> wb;
    return wb;
}

def add_application(wb: Workbench, app_id: str) -> App {
    if app_id in wb.apps {
        return wb.apps[app_id];
    }
    nd = App(app_id=app_id);
    wb.apps[app_id] = nd;
    wb +>:Owns:+> nd;
    root ++> nd;
    return nd;
}

def add_evidence(wb: Workbench, evid_id: str, app_id: str) -> Evidence {
    # ensure app exists
    app: App;
    if app_id in wb.apps {
        app = wb.apps[app_id];
    } else {
        app = add_application(wb, app_id);
    }
    if evid_id in wb.evidences {
        return wb.evidences[evid_id];
    }
    nd = Evidence(evid_id=evid_id);
    wb.evidences[evid_id] = nd;
    app +>:Contains:+> nd;
    root ++> nd;
    return nd;
}

def link_lineage(wb: Workbench, src_id: str, dst_id: str) -> bool {
    if src_id not in wb.evidences { return False; }
    if dst_id not in wb.evidences { return False; }
    src = wb.evidences[src_id];
    dst = wb.evidences[dst_id];
    src +>:Lineage:+> dst;
    return True;
}

def link_reference(wb: Workbench, src_id: str, dst_id: str) -> bool {
    if src_id not in wb.evidences { return False; }
    if dst_id not in wb.evidences { return False; }
    src = wb.evidences[src_id];
    dst = wb.evidences[dst_id];
    src +>:Reference:+> dst;
    return True;
}

def get_lineage(wb: Workbench, evid_id: str) -> list[str] {
    if evid_id not in wb.evidences { return []; }
    nd = wb.evidences[evid_id];
    w = nd spawn LineageWalker(claimed={}, found=[]);
    res: list[str] = w.found;
    return sorted(res);
}

def get_references(wb: Workbench, evid_id: str) -> list[str] {
    if evid_id not in wb.evidences { return []; }
    nd = wb.evidences[evid_id];
    w = nd spawn ReferenceWalker(claimed={}, found=[]);
    res: list[str] = w.found;
    return sorted(res);
}

def get_reachable_evidence(wb: Workbench, app_id: str) -> list[str] {
    if app_id not in wb.apps { return []; }
    nd = wb.apps[app_id];
    w = nd spawn ReachWalker(claimed={}, found=[]);
    res: list[str] = w.found;
    return sorted(res);
}

def get_all_evidence(wb: Workbench, app_id: str) -> list[str] {
    if app_id not in wb.apps { return []; }
    app = wb.apps[app_id];
    out: list[str] = [];
    for evid in [app ->:Contains:->][?:Evidence] {
        out.append(evid.evid_id);
    }
    return sorted(out);
}
