def make_store() -> TreeStore {
    anchor = Category(cid="__anchor__", name="__anchor__");
    root ++> anchor;
    st = TreeStore(graph_root=anchor, nodes={});
    return st;
}

def add_category(store: TreeStore, cid: str, name: str, parent_id: str | None = None) -> Category {
    nd = Category(cid=cid, name=name);
    if parent_id is not None {
        nd.parent_id = parent_id;
    }
    store.nodes[cid] = nd;
    if parent_id is not None {
        if parent_id in store.nodes {
            par = store.nodes[parent_id];
            par +>:TreeEdge:+> nd;
        }
    } else {
        store.graph_root +>:TreeEdge:+> nd;
    }
    return nd;
}

def get_children(store: TreeStore, cid: str) -> list[str] {
    if cid not in store.nodes {
        return [];
    }
    nd = store.nodes[cid];
    out: list[str] = [];
    for ch in [nd ->:TreeEdge:->][?:Category] {
        if ch.cid == "__anchor__" {
            continue;
        }
        out.append(ch.cid);
    }
    return sorted(out);
}

def get_descendants(store: TreeStore, cid: str, include_self: bool = False) -> list[str] {
    if cid not in store.nodes {
        return [];
    }
    start = store.nodes[cid];
    w = start spawn DescendantsWalker(claimed={}, collected=[], start_cid=cid);
    res: list[str] = w.collected;
    if include_self {
        res.append(cid);
    }
    return sorted(res);
}

def get_ancestors(store: TreeStore, cid: str, include_self: bool = False) -> list[str] {
    if cid not in store.nodes {
        return [];
    }
    out: list[str] = [];
    seen: dict[str, bool] = {};
    cur: str = "";
    if include_self {
        cur = cid;
    } else {
        nd0 = store.nodes[cid];
        if nd0.parent_id == "" {
            return [];
        }
        cur = nd0.parent_id;
    }
    while cur != "" {
        if cur in seen {
            break;
        }
        seen[cur] = True;
        if cur not in store.nodes {
            break;
        }
        out.append(cur);
        nd = store.nodes[cur];
        cur = nd.parent_id;
    }
    return sorted(out);
}

def get_root(store: TreeStore, cid: str) -> str | None {
    if cid not in store.nodes {
        return None;
    }
    cur: str = cid;
    seen: dict[str, bool] = {};
    while True {
        if cur in seen {
            break;
        }
        seen[cur] = True;
        nd = store.nodes[cur];
        if nd.parent_id == "" {
            break;
        }
        if nd.parent_id not in store.nodes {
            break;
        }
        cur = nd.parent_id;
    }
    return cur;
}

def get_roots(store: TreeStore) -> list[str] {
    out: list[str] = [];
    for k in store.nodes {
        nd = store.nodes[k];
        if nd.parent_id == "" {
            out.append(k);
        }
    }
    return sorted(out);
}

