def make_package(pid: str, compressed: int) -> Package {
    # bounded creation rejects over limit
    p = Package(pid=pid, compressed=compressed);
    if compressed > p.limit {
        p.evidence.append("compressed_limit");
    }
    return p;
}

def add_part(graph_root: Package, pid: str, path: str, ctype: str, size: int) -> Part | None {
    if "../" in path { graph_root.evidence.append("traversal:" + pid); return None; }
    if "..\\" in path { graph_root.evidence.append("traversal:" + pid); return None; }
    if size > graph_root.limit { graph_root.evidence.append("expansion:" + pid); return None; }
    for e in [graph_root ->:Contains:->][?:Part] { if e.path == path { graph_root.evidence.append("duplicate:" + path); return None; } }
    if ctype == "macro" { graph_root.evidence.append("macro:" + pid); return None; }
    if ctype == "executable" { graph_root.evidence.append("executable:" + pid); return None; }
    nd = Part(pid=pid, path=path, ctype=ctype, size=size);
    graph_root +>:Contains:+> nd;
    return nd;
}

def add_relationship(src: Part | None, dst: Part | None, rid: str, external: bool, graph_root: Package) -> bool {
    if src == None { return False; }
    if dst == None { return False; }
    s = src as Part;
    d = dst as Part;
    if external { graph_root.evidence.append("external:" + rid); return False; }
    s +>:Relates:+> d;
    return True;
}

def resolve_relationships(graph_root: Package, start: Part) -> list[str] {
    if graph_root.cancelled { return []; }
    w = start spawn ResolveWalker(claimed={});
    return w.order;
}

def collect_package(graph_root: Package) -> list[str] {
    w = graph_root spawn CollectWalker(claimed={});
    res: list[str] = w.found;
    return sorted(res);
}

def cancel_package(graph_root: Package) -> bool {
    if graph_root.cancelled { return False; }
    w = graph_root spawn DisposeWalker(claimed={});
    # walker mutates cancelled flag
    return graph_root.cancelled;
}
