    return p;
}

def create_task(sys: SysRoot, tid: str, pid: str) -> Task {
    t = Task(tid=tid, depth=0);
    sys.task_map[tid] = t;
    if pid in sys.profile_map {
        prof = sys.profile_map[pid] as AgentProfile;
        prof +>:Assigned:+> t;
    }
    return t;
}

def can_create_subtask(sys: SysRoot, pid: str) -> bool {
    if pid not in sys.profile_map { return False; }
    prof = sys.profile_map[pid] as AgentProfile;
    return prof.is_coordinator;
}

def add_dependency(sys: SysRoot, tid: str, depends_on: str) -> bool {
    if tid not in sys.task_map { return False; }
    if depends_on not in sys.task_map { return False; }
    a = sys.task_map[tid] as Task;
    b = sys.task_map[depends_on] as Task;
    a +>:Depends:+> b;
    return True;
}

def get_delegation_tree(sys: SysRoot, root_tid: str) -> list[str] {
    if root_tid not in sys.task_map { return []; }
    rt = sys.task_map[root_tid] as Task;
    w = rt spawn DelegationWalk(claimed={}, out=[]);
    res: list[str] = sorted(w.out);
    return res;
}

def get_dependency_closure(sys: SysRoot, tid: str) -> list[str] {
    if tid not in sys.task_map { return []; }
    rt = sys.task_map[tid] as Task;
    w = rt spawn DependWalk(claimed={}, out=[]);
    res: list[str] = sorted(w.out);
    return res;
}

def create_subtask(sys: SysRoot, parent_tid: str, child_tid: str, max_depth: int, max_total: int) -> bool {
    if parent_tid not in sys.task_map { return False; }
    if child_tid in sys.task_map { return False; }
    parent = sys.task_map[parent_tid] as Task;
    nd: int = parent.depth + 1;
    if nd > max_depth { return False; }
    # total volume bound per root — count reachable from parent
    cur: list[str] = get_delegation_tree(sys, parent_tid);
    if len(cur) + 1 > max_total { return False; }
    child = Task(tid=child_tid, depth=nd);
    sys.task_map[child_tid] = child;
    parent +>:Subtask:+> child;
    return True;
}

