```jac
node Workspace { has name: str = "ws"; }
node Repo { has name: str; }
node SrcFile { has repo: str; has path: str; has fid: str; }
node TstFile { has repo: str; has path: str; has via: str; has basis: str; has tid: str; has confidence_str: str = "0.0"; has call_site: str = ""; }

edge Contains {}
edge ContractEdge { has confidence: float = 0.0; has call_site: str = ""; }

walker ImpactWalker {
    has claimed: dict[str, bool] = {};
    has target_fids: dict[str, bool] = {};
    has results: list[dict[str, str]] = [];
    has tid_to_idx: dict[str, int] = {};
    has cur_source: str = "";

    can start_ws with Workspace entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        kids: list[Repo] = [here ->:Contains:->][?:Repo];
        if len(kids) == 0 { disengage; }
        for kid in kids { visit :0: [kid]; }
        print("walker start ws");
    }
    can step_repo with Repo entry {
        if here.name in self.claimed { skip; }
        self.claimed[here.name] = True;
        files: list[SrcFile] = [here ->:Contains:->][?:SrcFile];
        if len(files) == 0 { disengage; }
        for f in files { visit :0: [f]; }
        print("walker repo " + here.name);
    }
    can step_src with SrcFile entry {
        if here.fid in self.claimed { skip; }
        self.claimed[here.fid] = True;
        if here.fid not in self.target_fids { skip; }
        self.cur_source = here.fid;
        kids: list[TstFile] = [here ->:ContractEdge:->][?:TstFile];
        if len(kids) == 0 { disengage; }
        for kid in kids { visit :0: [kid]; }
        print("walker src " + here.fid);
    }
    can step_test with TstFile entry {
        if here.tid in self.claimed {
            idx: int = self.tid_to_idx[here.tid];
            cur: dict[str, str] = self.results[idx];
            got: str = cur["source_files"];
            if got == "" {
                cur["source_files"] = self.cur_source;
            } else {
                cur["source_files"] = got + "," + self.cur_source;
            }
            self.results[idx] = cur;
            skip;
        }
        self.claimed[here.tid] = True;
        d: dict[str, str] = {};
        d["repo"] = here.repo;
        d["path"] = here.path;
        d["basis"] = here.basis;
        d["via"] = here.via;
        d["confidence"] = here.confidence_str;
        d["source_files"] = self.cur_source;
        d["call_site"] = here.call_site;
        self.tid_to_idx[here.tid] = len(self.results);
        self.results.append(d);
        print("walker test " + here.tid);
    }
}

def create_workspace() -> Workspace {
    ws = Workspace(name="ws");
    return ws;
}

def add_repo(ws: Workspace, repo_name: str) -> Repo {
    # check existing
    existing: list[Repo] = [ws ->:Contains:->][?:Repo];
    for r in existing { if r.name == repo_name { return r; } }
    nd = Repo(name=repo_name);
    ws +>:Contains:+> nd;
    return nd;
}

def add_provider_file(ws: Workspace, repo: str, path: str) -> SrcFile {
    rn = add_repo(ws, repo);
    fid: str = repo + ":" + path;
    # dedup
    files: list[SrcFile] = [rn ->:Contains:->][?:SrcFile];
    for f in files { if f.fid == fid { return f; } }
    nd = SrcFile(repo=repo, path=path, fid=fid);
    rn +>:Contains:+> nd;
    return nd;
}

def add_consumer_test(ws: Workspace, repo: str, path: str, via: str, basis: str, confidence: float, call_site: str) -> TstFile {
    rn = add_repo(ws, repo);
    tid: str = repo + ":" + path;
    files: list[TstFile] = [rn ->:Contains:->][?:TstFile];
    for f in files { if f.tid == tid { return f; } }
    nd = TstFile(repo=repo, path=path, via=via, basis=basis, tid=tid, confidence_str=str(confidence), call_site=call_site);
    rn +>:Contains:+> nd;
    return nd;
}

def add_contract_link(ws: Workspace, provider_repo: str, provider_path: str, consumer_repo: str, test_path: str, via: str, basis: str, confidence: float, call_site: str) -> None {
    src = add_provider_file(ws, provider_repo, provider_path);
    tst = add_consumer_test(ws, consumer_repo, test_path, via, basis, confidence, call_site);
    # update tst fields to reflect latest link (single source view)
    tst.via = via;
    tst.basis = basis;
    tst.confidence_str = str(confidence);
    tst.call_site = call_site;
    src +>:ContractEdge:+> tst;
}

def get_workspace_test_impact(ws: Workspace, changed_files: list[dict[str, str]]) -> list[dict[str, str]] {
    # build target set
    target: dict[str, bool] = {};
    for cf in changed_files {
        repo: str = cf["repo"];
        path: str = cf["path"];
        fid: str = repo + ":" + path;
        target[fid] = True;
    }
    w = ws spawn ImpactWalker(target_fids=target, claimed={}, results=[], tid_to_idx={}, cur_source="");
    # walker runs synchronously; collect
    out: list[dict[str, str]] = w.results;
    # deterministic sort by repo, path
    i: int = 0;
    while i < len(out) {
        j: int = i + 1;
        while j < len(out) {
            a: dict[str, str] = out[i];
            b: dict[str, str] = out[j];
            swap: bool = False;
            if a["repo"] > b["repo"] { swap = True; }
            if a["repo"] == b["repo"] and a["path"] > b["path"] { swap = True; }
            if swap {
                tmp: dict[str, str] = out[i];
                out[i] = out[j];
                out[j] = tmp;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    return out;
}

