    for nd in [graph_root ->:Contains:->][?:SrcFile] {
        if nd.fid == fid { return; }
    }
    nd2 = SrcFile(repo=repo, path=path, fid=fid);
    graph_root ++>:Contains:+> nd2;
}

def add_contract_link(graph_root: Workspace, provider_repo: str, provider_path: str, consumer_repo: str, consumer_path: str, confidence: float) -> None {
    pfid: str = provider_repo + ":" + provider_path;
    cfid: str = consumer_repo + ":" + consumer_path;
    pnode: SrcFile | None = None;
    cnode: SrcFile | None = None;
    for nd in [graph_root ->:Contains:->][?:SrcFile] {
        if nd.fid == pfid { pnode = nd; }
        if nd.fid == cfid { cnode = nd; }
    }
    if pnode is None {
        pnode = SrcFile(repo=provider_repo, path=provider_path, fid=pfid);
        graph_root ++>:Contains:+> pnode;
    }
    if cnode is None {
        cnode = SrcFile(repo=consumer_repo, path=consumer_path, fid=cfid);
        graph_root ++>:Contains:+> cnode;
    }
    pn: SrcFile = pnode as SrcFile;
    cn: SrcFile = cnode as SrcFile;
    pn +>:ContractLink(confidence=confidence):+> cn;
}

def add_test_reachability(graph_root: Workspace, consumer_repo: str, consumer_path: str, test_repo: str, test_path: str, via: str, basis: str) -> None {
