    tid: str = test_repo + ":" + test_path;
    cnode: SrcFile | None = None;
    tnode: TestFile | None = None;
    for nd in [graph_root ->:Contains:->][?:SrcFile] {
        if nd.fid == cfid { cnode = nd; }
    }
    for nd2 in [graph_root ->:Contains:->][?:TestFile] {
        if nd2.tid == tid { tnode = nd2; }
    }
    if cnode is None {
        cnode = SrcFile(repo=consumer_repo, path=consumer_path, fid=cfid);
        graph_root ++>:Contains:+> cnode;
    }
    if tnode is None {
        tnode = TestFile(repo=test_repo, path=test_path, tid=tid);
        graph_root ++>:Contains:+> tnode;
    }
    cn2: SrcFile = cnode as SrcFile;
    tn2: TestFile = tnode as TestFile;
    cn2 +>:ReachLink(via=via, basis=basis):+> tn2;
}

