def find_sub(groot: Anchor, sid: str) -> Subscription | None {
    subs: list[Subscription] = [groot -->][?:Subscription];
    for s in subs {
        if s.sid == sid { return s; }
    }
    return None;
}

def create_subscription(groot: Anchor, sid: str, user_id: str, is_folder: bool, unread: int) -> Subscription {
    nd = Subscription(sid=sid, user_id=user_id, is_folder=is_folder, unread=unread);
    groot ++> nd;
    return nd;
}

def set_parent(groot: Anchor, child_id: str, parent_id: str | None = None) -> bool {
    child = find_sub(groot, child_id);
    if child is None { return False; }
    if parent_id is None { return True; }
    if parent_id == child_id { return False; }
    parent = find_sub(groot, parent_id);
    if parent is None { return False; }
    if not parent.is_folder { return False; }
    if parent.user_id != child.user_id { return False; }
    w = parent spawn AncestorWalk(claimed={}, chain=[]);
    for anc in w.chain {
        if anc == child_id { return False; }
    }
    child +>:Parent:+> parent;
    return True;
}

def get_unread_count(groot: Anchor, sid: str) -> int {
    sub = find_sub(groot, sid);
    if sub is None { return 0; }
    w = sub spawn SubtreeWalk(claimed={}, total=0, collected=[]);
    return w.total;
}

def get_unread_posts(groot: Anchor, sid: str) -> list[str] {
    sub = find_sub(groot, sid);
    if sub is None { return []; }
    w = sub spawn SubtreeWalk(claimed={}, total=0, collected=[]);
    res: list[str] = [];
    for cid in w.collected {
        nd = find_sub(groot, cid);
        if nd is not None {
            if nd.unread > 0 { res.append(cid); }
        }
    }
    return sorted(res);
}

def get_paginated_posts(groot: Anchor, sid: str, limit: int = 10, offset: int = 0) -> list[str] {
    all_posts = get_unread_posts(groot, sid);
    out: list[str] = [];
    idx: int = 0;
    for p in all_posts {
        if idx >= offset {
            if len(out) < limit { out.append(p); }
        }
        idx += 1;
    }
    return out;
}

def mark_read(groot: Anchor, sid: str) -> None {
    sub = find_sub(groot, sid);
    if sub is None { return; }
    w = sub spawn SubtreeWalk(claimed={}, total=0, collected=[]);
    for cid in w.collected {
        nd = find_sub(groot, cid);
        if nd is not None { nd.unread = 0; }
    }
}

def get_unread_subscription_list_for_user(groot: Anchor, user_id: str) -> list[str] {
    subs: list[Subscription] = [groot -->][?:Subscription];
    seen: dict[str, bool] = {};
    acc: list[str] = [];
    for s in subs {
        if s.user_id == user_id {
            if s.unread > 0 {
                if s.sid not in seen {
                    seen[s.sid] = True;
                    acc.append(s.sid);
                }
            }
        }
    }
    return sorted(acc);
}

