    can descend with Org entry {
        if here.id in self.claimed {
            skip;
        }
        self.claimed[here.id] = True;
        print("descendant " + here.id);

        if here.id != self.origin_id {
            self.found.append(here.id);
        }
        if self.depths[here.id] >= 20 {
            skip;
        }
        for child in [here <-:ParentOf:<-][?:Org] {
