    index: OrgIndex,
    user_id: str,
    org_id: str,
    role: str
) -> bool {
    target: Org | None = None;
    for candidate in index.orgs {
        if candidate.id == org_id {
            target = candidate;
        }
    }
    if target is None {
        return False;
    }

    claimed: dict[str, bool] = {};
    depths: dict[str, int] = {};
    depths[target.id] = 0;
    walker = target spawn AncestorRoleWalker(
        user_id=user_id,
        role=role,
        origin_id=target.id,
        claimed=claimed,
        depths=depths
    );
    return walker.allowed;
}

def getDescendantOrgIds(index: OrgIndex, org_id: str) -> list[str] {
    target: Org | None = None;
    for candidate in index.orgs {
        if candidate.id == org_id {
            target = candidate;
        }
    }
    if target is None {
        return [];
    }

    claimed: dict[str, bool] = {};
    depths: dict[str, int] = {};
    depths[target.id] = 0;
    walker = target spawn DescendantWalker(
        origin_id=target.id,
        claimed=claimed,
        depths=depths
    );
    return sorted(walker.found);
}

def getEditableOrgIdsForUser(
    index: OrgIndex,
    user_id: str
) -> list[str] {
    if user_id not in index.user_orgs {
        return [];
    }

    own_org = index.user_orgs[user_id];
    ids: list[str] = [own_org.id];
    descendants = getDescendantOrgIds(index, own_org.id);
    for descendant_id in descendants {
        ids.append(descendant_id);
    }
    return sorted(ids);
}
