def find_intent(catalog: WorkflowCatalog, name: str) -> Intent | None {
    for item in catalog.intents {
        if item.name == name { return item; }
    }
    return None;
}

def find_worker(catalog: WorkflowCatalog, name: str) -> WorkerCapability | None {
    for item in catalog.workers {
        if item.name == name { return item; }
    }
    return None;
}

def new_catalog() -> WorkflowCatalog {
    return WorkflowCatalog(graph_root=CatalogRoot());
}

def register_worker(catalog: WorkflowCatalog, name: str) -> bool {
    if find_worker(catalog, name) != None { return False; }
    worker = WorkerCapability(name=name);
    catalog.graph_root ++> worker;
    catalog.workers.append(worker);
    return True;
}

def register_intent(catalog: WorkflowCatalog, name: str) -> bool {
    if find_intent(catalog, name) != None { return False; }
    intent = Intent(name=name);
    catalog.graph_root ++> intent;
    catalog.intents.append(intent);
    return True;
}

def allow_capability(catalog: WorkflowCatalog, intent_name: str, worker_name: str) -> bool {
    intent = find_intent(catalog, intent_name);
    worker = find_worker(catalog, worker_name);
    if intent == None or worker == None { return False; }
    for allowed in [intent ->:Provides:->][?:WorkerCapability] {
        if allowed.name == worker_name { return False; }
    }
    intent +>:Provides:+> worker;
    return True;
}

def add_dependency(catalog: WorkflowCatalog, parent_name: str, child_name: str) -> bool {
    parent = find_intent(catalog, parent_name);
    child = find_intent(catalog, child_name);
    if parent == None or child == None { return False; }
    for existing in [parent ->:Requires:->][?:Intent] {
        if existing.name == child_name { return False; }
    }
    parent +>:Requires:+> child;
    return True;
}

def allowed_workers(catalog: WorkflowCatalog, intent_name: str) -> list[str] {
    result: list[str] = [];
    intent = find_intent(catalog, intent_name);
    if intent == None { return result; }
    for worker in [intent ->:Provides:->][?:WorkerCapability] {
        result.append(worker.name);
    }
    return sorted(result);
}

def dependency_order(catalog: WorkflowCatalog, intent_name: str) -> list[str] {
    result: list[str] = [];
    intent = find_intent(catalog, intent_name);
    if intent == None { return result; }
    walk = intent spawn DependencyWalk(claimed={});
    result = sorted(walk.names);
    return result;
}

def create_workflow(catalog: WorkflowCatalog, intent_name: str, worker_name: str) -> bool {
    intent = find_intent(catalog, intent_name);
    worker = find_worker(catalog, worker_name);
    if intent == None or worker == None { return False; }
    permitted: bool = False;
    for allowed in [intent ->:Provides:->][?:WorkerCapability] {
        if allowed.name == worker_name { permitted = True; }
    }
    if not permitted { return False; }
    job = WorkflowJob(intent_name=intent_name, capability_name=worker_name);
    catalog.graph_root ++> job;
    intent +>:Dispatches:+> job;
    worker +>:Runs:+> job;
    catalog.jobs.append(job);
    return True;
}

def queued_work(catalog: WorkflowCatalog) -> list[str] {
    result: list[str] = [];
    for job in catalog.jobs {
        result.append(job.intent_name + ":" + job.capability_name);
    }
    return result;
}
