        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print "render " + here.block_id;

        section: str = "## " + here.block_id + "\n\n";
        section = section + "**" + here.title + "**\n\n";
        section = section + preview_block(here) + "\n\n";

        choice_ids: list[str] = [];
        for choice in [here ->:HasChoice:->][?:Choice] {
            choice_ids.append(choice.choice_id);
        }
        choice_ids = sorted(choice_ids);

        kids: list[Block] = [];
        for choice_id in choice_ids {
            for choice in [here ->:HasChoice:->][?:Choice] {
                if choice.choice_id == choice_id {
                    for target in [choice ->:ChoiceTarget:->][?:Block] {
                        section = section + "- [" + choice.label + "](#"
                            + target.block_id + ")\n";
                        kids.append(target);
                    }
