    }
    return None;
}

def _add_columns(
    relation: Relation,
    names: list[str],
    non_null: list[str],
    unique_names: list[str]
) {
    position = 0;
    for name in names {
        required = False;
        unique_column = False;
        for required_name in non_null {
            if required_name == name { required = True; }
        }
        for unique_name in unique_names {
            if unique_name == name { unique_column = True; }
        }
        column = OutputColumn(
            name=name,
            position=position,
            nullable=required == False,
            unique=unique_column
        );
        relation +>:Needs:+> column;
        position += 1;
    }
}

def _rebuild_final(
    program: Program, hydration: DatabaseHydration
) -> Program {
    final_program = Program(name=program.name + ":final");

    for relation in [program ->:Contains:->][?:Relation] {
        row = _find_catalog(hydration.rows, relation.qualified_name);
        copy = Relation(
            qualified_name=relation.qualified_name,
            kind=relation.kind,
            external=False,
            unique=relation.unique
        );
        final_program +>:Contains:+> copy;
        if row == None {
            _add_columns(
                copy,
                relation.columns,
                relation.non_null_columns,
                relation.unique_columns
            );
        } else {
            copy.kind = row.kind;
            copy.unique = row.unique;
            _add_columns(
                copy, row.columns, row.non_null_columns, row.unique_columns
            );
        }
    }

    for row in hydration.rows {
        existing = _find_relation(final_program, row.name);
        if existing == None {
            added = Relation(
                qualified_name=row.name,
                kind=row.kind,
                external=False,
                unique=row.unique
            );
            final_program +>:Contains:+> added;
            _add_columns(
                added, row.columns, row.non_null_columns, row.unique_columns
            );
        }
    }

    for row in hydration.rows {
        target = _find_relation(final_program, row.name);
        if target != None {
            if row.kind == "view" {
                definition = DatabaseViewDefinition(sql=row.sql);
                target +>:Defines:+> definition;
            }
            for child in [row ->:CatalogDepends:->][?:DatabaseRelationMetadata] {
                child_target = _find_relation(final_program, child.name);
                if child_target != None {
                    target +>:DependsOn:+> child_target;
                }
            }
        }
    }
    return final_program;
}

def hydrate(program: Program) -> DatabaseHydration {
    closure = program spawn CatalogClosure(claimed={});
    hydration = DatabaseHydration(rows=closure.found);
    hydration.final_program = _rebuild_final(program, hydration);
    return hydration;
}

def bind(
    program: Program, hydration: DatabaseHydration
) -> list[Knowledge] {
    facts: list[Knowledge] = [];
    for row in hydration.rows {
        relation = _find_relation(program, row.name);
        if relation != None {
            if relation.unique == True {
                facts.append(Knowledge(fact="UniqueSet", relation=relation));
            }
            for column in [relation ->:Needs:->][?:OutputColumn] {
                if column.nullable == False {
                    facts.append(
                        Knowledge(
                            fact="NonNullColumn",
                            relation=relation,
                            column=column
                        )
                    );
                }
                if column.unique == True {
                    facts.append(
                        Knowledge(
                            fact="UniqueSetColumn",
                            relation=relation,
                            column=column,
                            position=column.position
                        )
                    );
                }
            }
        }
    }
    return facts;
}

