    fetcher: DatabaseKnowledgeFetcher,
    program: Program
) -> DatabaseHydration {
    reach = program spawn ReachWalker(claimed={}, found=[]);
    initial: list[RelationMetadata] = fetch_relation_metadata(fetcher, reach.found);
    result = DatabaseHydration();
    for row in initial {
        expanded = row spawn ExpandWalker(claimed={}, found=[]);
        for item in expanded.found {
            known: bool = False;
            for prior in result.metadata {
                if prior.qname == item.qname { known = True; }
            }
            if known == False {
                result.metadata.append(item);
                result.relation_names.append(item.qname);
                if item.is_view == True {
                    result.view_names.append(item.qname);
                    result.definitions.append(fetch_view_definition(fetcher, item));
                }
            }
        }
    }
    return result;
}

def rebuild_program(
    program: Program,
    hydration: DatabaseHydration
) -> Program {
    final_program = Program(source=program.source);
    for meta in hydration.metadata {
        sql: str = "";
        for definition in hydration.definitions {
            if definition.qname == meta.qname { sql = definition.sql; }
        }
        rel = Relation(
            qname=meta.qname,
            external=meta.external,
            is_view=meta.is_view,
            definition=sql
        );
        final_program +>:Uses:+> rel;
    }
    return final_program;
}

def bind(
    program: Program,
    hydration: DatabaseHydration
) -> list[Knowledge] {
    walker = program spawn BindWalker(claimed={}, unique_done={}, facts=[]);
    return walker.facts;
}

def analyze(
    fetcher: DatabaseKnowledgeFetcher,
    program: Program
) -> list[Knowledge] {
    hydration = hydrate(fetcher, program);
    final_program = rebuild_program(program, hydration);
    return bind(final_program, hydration);
}
