    has found: list[str] = [];

    can step with Part entry {
        if here.path in self.claimed { skip; }
        self.claimed[here.path] = True;
        self.found.append(here.path);
        print("resolve " + here.path);
        for target in [here ->:Relationship:->][?:Part] {
            visit :0: [target];
        }
    }
