        if dep_state == "failed" {
            report.dependency_state = "failed";
        } elif dep_state == "unknown" and report.dependency_state != "failed" {
            report.dependency_state = "unknown";
        } elif dep_state == "degraded" and report.dependency_state == "healthy" {
            report.dependency_state = "degraded";
        }
    }

    for dep in [target ->:OptionalDependency:->][?:Service] {
        dep_stale: bool = dep.observed_age > dep.stale_after;
        report.dependency_evidence.append(DependencyEvidence(
            target_id=dep.service_id,
            target_state=dep.local_state,
            local_state=dep.local_state,
            relation_type="optional",
            observation_age=dep.observed_age,
            stale=dep_stale
        ));
    }

    report.cycle_detected = walker.cycle_detected;
    if target.local_state == "failed" or target.application_failed {
        report.effective_state = "failed";
    } elif walker.states[service_id] == "degraded" or report.dependency_state != "healthy" {
        report.effective_state = "degraded";
    } elif walker.states[service_id] == "unknown" {
        report.effective_state = "unknown";
    } else {
        report.effective_state = walker.states[service_id];
