    worker_names: list[str] | None = None
) -> bool {
    if name == "" {
        return False;
    }
    if name in catalog.workflows {
        return False;
    }
    if worker_names != None {
        for worker_name in worker_names {
            if worker_name not in catalog.public_workers {
                return False;
            }
        }
    }
    workflow = Workflow(name=name);
    catalog.workflows[name] = workflow;
    catalog +>:Contains:+> workflow;
    if worker_names != None {
        for worker_name in worker_names {
            worker = catalog.workers[worker_name];
            workflow +>:Uses:+> worker;
        }
    }
    return True;
}

def link_workflow(catalog: Catalog, parent_name: str, child_name: str) -> bool {
    if parent_name not in catalog.workflows {
        return False;
    }
    if child_name not in catalog.workflows {
        return False;
    }
    if parent_name == child_name {
        return False;
    }
    parent = catalog.workflows[parent_name];
    child = catalog.workflows[child_name];
    parent +>:Depends:+> child;
    return True;
}

def workflow_reaches(catalog: Catalog, source_name: str, target_name: str) -> bool {
    if source_name not in catalog.workflows {
        return False;
    }
    if target_name not in catalog.workflows {
        return False;
    }
    graph_root = catalog;
    walker = graph_root spawn Reachability(
        source_name=source_name,
        target_name=target_name,
        claimed={}
    );
    return walker.found;
}

def workflow_workers(catalog: Catalog, workflow_name: str) -> list[str] {
    names: list[str] = [];
    if workflow_name not in catalog.workflows {
        return names;
    }
    graph_root = catalog;
    walker = graph_root spawn WorkerNames(
        workflow_name=workflow_name,
        claimed={}
    );
    names = walker.names;
    return sorted(names);
}
