"""OSP lift for F3-Nation/f3-nation#917."""

node Org {
    has cid: str;
    has org_type: str;
}

node User {
    has uid: str;
    has org_id: str;
    has role: str;
}

edge ParentChild {}
edge ChildParent {}

obj OrgStore {
    has orgs: dict[str, Org] = {};
    has users: dict[str, User] = {};
}

walker AncestorRoleWalk {
    has claimed: dict[str, bool] = {};
    has depths: dict[str, int] = {};
    has found_role: bool = False;
    has user_org_id: str = "";
    has requested_role: str = "";
    has max_depth: int = 20;

    can step with Org entry {
        if here.cid in self.claimed { skip; }
        if here.cid not in self.depths {
            self.depths[here.cid] = 0;
        }
        if self.depths[here.cid] > self.max_depth { skip; }

        self.claimed[here.cid] = True;
        print("ancestor " + here.cid);

        if here.cid == self.user_org_id {
            if self.requested_role == "admin" {
                self.found_role = True;
            }
        }

        if self.depths[here.cid] < self.max_depth {
            for parent in [here ->:ChildParent:->][?:Org] {
                if parent.cid not in self.depths {
                    self.depths[parent.cid] = self.depths[here.cid] + 1;
                }
                visit :0: [parent];
            }
        }
    }
}

walker DescendantWalk {
    has claimed: dict[str, bool] = {};
    has depths: dict[str, int] = {};
    has found: list[str] = [];
    has start_id: str = "";
    has include_start: bool = False;
    has max_depth: int = 20;

    can step with Org entry {
        if here.cid in self.claimed { skip; }
        if here.cid not in self.depths {
            self.depths[here.cid] = 0;
        }
        if self.depths[here.cid] > self.max_depth { skip; }

        self.claimed[here.cid] = True;
        print("descendant " + here.cid);

        if self.include_start {
            self.found.append(here.cid);
        } elif here.cid != self.start_id {
            self.found.append(here.cid);
        }

        if self.depths[here.cid] < self.max_depth {
            for child in [here ->:ParentChild:->][?:Org] {
                if child.cid not in self.depths {
                    self.depths[child.cid] = self.depths[here.cid] + 1;
                }
                visit :0: [child];
            }
        }
    }
}

def newOrgStore() -> OrgStore {
    return OrgStore();
}

def addOrg(
    tree: OrgStore,
    org_id: str,
    org_type: str,
    parent_id: str | None = None
) -> None {
    org = Org(cid=org_id, org_type=org_type);
    tree.orgs[org_id] = org;

    if parent_id is not None {
        if parent_id in tree.orgs {
            parent = tree.orgs[parent_id];
            parent +>:ParentChild:+> org;
            org +>:ChildParent:+> parent;
        }
    }
    return None;
}

def connectOrg(tree: OrgStore, parent_id: str, child_id: str) -> None {
    if parent_id not in tree.orgs { return None; }
    if child_id not in tree.orgs { return None; }

    parent = tree.orgs[parent_id];
    child = tree.orgs[child_id];
    parent +>:ParentChild:+> child;
    child +>:ChildParent:+> parent;
    return None;
}

def addUser(
    tree: OrgStore,
    user_id: str,
    org_id: str,
    role: str
) -> None {
    tree.users[user_id] = User(uid=user_id, org_id=org_id, role=role);
    return None;
}

def checkHasRoleOnOrg(
    tree: OrgStore,
    user_id: str,
    org_id: str,
    role: str
) -> bool {
    if user_id not in tree.users { return False; }
    if org_id not in tree.orgs { return False; }

    user = tree.users[user_id];
    start = tree.orgs[org_id];
    walk = start spawn AncestorRoleWalk(
        claimed={},
        user_org_id=user.org_id,
        requested_role=role
    );
    return walk.found_role;
}

def getDescendantOrgIds(tree: OrgStore, org_id: str) -> list[str] {
    found: list[str] = [];
    if org_id not in tree.orgs { return found; }

    start = tree.orgs[org_id];
    walk = start spawn DescendantWalk(
        claimed={},
        start_id=org_id,
        include_start=False
    );
    return walk.found;
}

def getEditableOrgIdsForUser(
    tree: OrgStore,
    user_id: str
) -> list[str] {
    found: list[str] = [];
    if user_id not in tree.users { return found; }

    user = tree.users[user_id];
    if user.org_id not in tree.orgs { return found; }

    start = tree.orgs[user.org_id];
    walk = start spawn DescendantWalk(
        claimed={},
        start_id=user.org_id,
        include_start=True
    );
    return walk.found;
}
