        }
        self.claimed[here.cid] = True;
        for part in [here ->:Contains:->][?:Part] {
            visit :0: [part];
        }
        print("scan-package");
    }

    can scan_part with Part entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if here.name == self.wanted {
            self.found = here;
        }
        print(here.name);
    }
}

walker ResolveRelationships {
    has start_name: str;
    has found: list[str] = [];
    has evidence: list[str] = [];
    has claimed: dict[str, bool] = {};

    can resolve_package with Package entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        for part in [here ->:Contains:->][?:Part] {
            if part.name == self.start_name {
