def delegate(
    graph_root: Task,
    parent: Task,
    child: Task,
    actor: AgentProfile
) -> bool {
    if (actor.coordinator == False) {
        return False;
    }
    if (parent.owner_id != actor.profile_id) {
        return False;
    }
    if (parent.root_id != graph_root.task_id) {
        return False;
    }
    if (child.task_id == "" or child.parent_id != "") {
        return False;
    }
    if (parent.depth >= graph_root.max_depth) {
        return False;
    }
    if (graph_root.total_subtasks >= graph_root.max_total) {
        return False;
    }
    child.owner_id = actor.profile_id;
    child.root_id = graph_root.task_id;
    child.parent_id = parent.task_id;
    child.depth = parent.depth + 1;
    parent +>:child_of:+> child;
    graph_root.total_subtasks += 1;
    return True;
}

def add_dependency(task: Task, prerequisite: Task, actor: AgentProfile) -> bool {
