    if scan.found_source != None { return scan.found_source; }
    if scan.found_repo == None { return None; }
    source_node = Source(repo=repo_name, path=source_path);
    scan.found_repo +>:Owns:+> source_node;
    return source_node;
}

def link_contract(
    index: WorkspaceIndex,
    provider_repo: str,
    provider_path: str,
    consumer_repo: str,
    consumer_path: str,
    confidence: str
) -> None {
    provider_scan = catalog(index, provider_repo, provider_path);
    consumer_scan = catalog(index, consumer_repo, consumer_path);
    if provider_scan.found_source == None { return None; }
    if consumer_scan.found_source == None { return None; }
    consumer_scan.found_source.contract_confidence = confidence;
    provider_scan.found_source +>:Contract:+> consumer_scan.found_source;
    return None;
}

def register_test(
    index: WorkspaceIndex,
    repo_name: str,
    test_path: str,
    source_path: str,
    basis: str,
    via: str,
    confidence: str
) -> Test | None {
    scan = catalog(index, repo_name, source_path);
    if scan.found_repo == None { return None; }
    if scan.found_source == None { return None; }
    label = f"{repo_name}:{test_path}|{basis}|{via}|{confidence}|{source_path}";
    test_node = Test(
        repo=repo_name,
        path=test_path,
        basis=basis,
        via=via,
        confidence=confidence,
        source_path=source_path,
        label=label
    );
    scan.found_repo +>:Owns:+> test_node;
    scan.found_source +>:Covers:+> test_node;
    return test_node;
}

def get_workspace_test_impact(
    index: WorkspaceIndex,
    changed_repo: str,
    changed_path: str
) -> list[str] {
    scan = catalog(index, changed_repo, changed_path);
    if scan.found_source == None { return []; }
    walker = scan.found_source spawn ImpactWalker(
        changed_repo=changed_repo,
        claimed={},
        results=[]
    );
    return sorted(walker.results);
}
