    return Store(graph_root=graph_root);
}

def add_subscription(
    store: Store,
    sid: str,
    owner: str,
    label: str,
    folder: bool = False,
    unread_posts: list[str] | None = None
) -> bool {
    if locate(store, sid) is not None {
        return False;
    }
    if unread_posts is None {
        unread_posts = [];
    }
    sub = Subscription(
        sid=sid,
        owner=owner,
        label=label,
        folder=folder,
        unread_posts=unread_posts
    );
    store.graph_root +>:Catalog:+> sub;
    return True;
}

