    }
    if child.sid == parent.sid or child.owner != parent.owner {
        return False;
    }
    if not parent.folder or child.parent_sid is not None {
        return False;
    }
    probe = parent spawn Closure(target=child.sid);
    if probe.found {
        return False;
    }
    parent +>:Parent:+> child;
    child.parent_sid = parent.sid;
    return True;
}

