            selected.append(post);
        }
        index = index + 1;
    }
    return selected;
}

def mark_read(store: Store, sid: str) -> int {
    sub = locate(store, sid);
    if sub is None {
        return 0;
    }
    walk = sub spawn Closure(collect=True);
    cleared: int = walk.total;
    for child_sid in walk.ids {
        child = locate(store, child_sid);
        if child is not None {
            empty_posts: list[str] = [];
            child.unread_posts = empty_posts;
        }
    }
    return cleared;
}

def get_unread_subscription_list_for_user(
    store: Store,
    owner: str
) -> list[str] {
    scan = store.graph_root spawn CatalogScan(
        target="",
        owner=owner,
        collect_owner=True
    );
    return sorted(scan.ids);
