    workflow_name: str,
    capability_name: str
) -> bool {
    var known: bool = False;
    for capability in [registry ->:Registers:->][?:WorkerCapability] {
        if capability.name == capability_name {
            known = True;
        }
    }
    if known == False {
        return False;
    }
    for intent in [registry ->:Publishes:->][?:WorkflowIntent] {
        if intent.name == workflow_name {
            return False;
        }
    }
    intent = WorkflowIntent(
        name=workflow_name,
        capability_name=capability_name,
        public=True
    );
    registry +>:Publishes:+> intent;
    for capability in [registry ->:Registers:->][?:WorkerCapability] {
        if capability.name == capability_name {
            intent +>:Targets:+> capability;
        }
    }
    return True;
}

def queue_workflow(
    registry: WorkflowRegistry, workflow_name: str
) -> bool {
    audit = registry spawn BoundaryAudit(
        wanted=workflow_name,
        claimed={}
    );
    return audit.matched;
}

def public_capabilities(registry: WorkflowRegistry) -> list[str] {
    audit = registry spawn BoundaryAudit(claimed={});
