    return service;
}

def find_service(board: HealthBoard, service_id: str) -> Service | None {
    for service in board.services {
        if service.service_id == service_id {
            return service;
        }
    }
    return None;
}

def add_required_dependency(board: HealthBoard, source_id: str, target_id: str) -> bool {
    source = find_service(board, source_id);
    target = find_service(board, target_id);
    if source == None || target == None {
        return False;
    }
    source +>:RequiredDepends:+> target;
    return True;
}

def add_optional_dependency(board: HealthBoard, source_id: str, target_id: str) -> bool {
    source = find_service(board, source_id);
    target = find_service(board, target_id);
    if source == None || target == None {
        return False;
    }
    source +>:OptionalDepends:+> target;
    return True;
}

def local_status(service: Service) -> str {
    if service.local_state == "failed" || service.local_state == "fail" {
        return "fail";
    }
    if service.local_state == "degraded" || service.local_state == "unknown" {
        return "warn";
    }
    return "ok";
}

def evaluate_service(service: Service, now: int) -> None {
    service.required_dependencies = [];
    service.blocked_by = [];
    service.dependency_evidence = [];
    service.stale_evidence = [];
    service.dependency_state = "ok";
    service.observation_age = now - service.observed_at;
    if service.observation_age < 0 {
        service.observation_age = 0;
    }
    if service.observed_at <= 0 || service.observation_age > 300 {
        service.stale_evidence.append("self");
    }

    for dependency in [service ->:RequiredDepends:->][?:Service] {
        service.required_dependencies.append(dependency.service_id);
        service.dependency_evidence.append(
            dependency.service_id + ":" + dependency.effective_state + ":required"
        );
        if dependency.observed_at <= 0 || now - dependency.observed_at > 300 {
            service.stale_evidence.append(dependency.service_id);
            service.blocked_by.append(dependency.service_id);
            service.dependency_state = "warn";
        }
        if dependency.effective_state == "fail" ||
           dependency.effective_state == "warn" ||
           dependency.effective_state == "unknown" {
            service.blocked_by.append(dependency.service_id);
            service.dependency_state = "warn";
        }
    }

    if service.cycle_detected {
        service.blocked_by.append("cycle:" + service.service_id);
        service.dependency_state = "warn";
    }
    if service.local_state == "failed" || service.local_state == "fail" {
        service.effective_state = "fail";
    } elif service.dependency_state == "warn" || len(service.stale_evidence) > 0 {
        service.effective_state = "warn";
    } elif service.local_state == "degraded" || service.local_state == "unknown" {
        service.effective_state = "warn";
    } else {
        service.effective_state = "ok";
    }
}

def reconcile_health(board: HealthBoard, now: int) -> list[Service] {
    for service in board.services {
        service.effective_state = local_status(service);
        service.dependency_state = "ok";
        service.cycle_detected = False;
        service.required_dependencies = [];
        service.blocked_by = [];
        service.dependency_evidence = [];
        service.stale_evidence = [];
    }

    for service in board.services {
        walker = service spawn DependencyWalker(
            claimed={}, found=[], origin_id=service.service_id
        );
        for current in walker.found {
            if walker.cycle_hit {
                current.cycle_detected = True;
            }
        }
        idx = len(walker.found) - 1;
        while idx >= 0 {
            evaluate_service(walker.found[idx], now);
            idx -= 1;
        }
    }
    return board.services;
}

def health_payload(service: Service) -> HealthPayload {
    return HealthPayload(
        local_state=service.local_state,
        dependency_state=service.dependency_state,
        effective_state=service.effective_state,
        required_dependencies=service.required_dependencies,
        blocked_by=service.blocked_by,
        dependency_evidence=service.dependency_evidence,
        observation_age=service.observation_age,
        stale_evidence=service.stale_evidence
    );
}
