                    if source != None {
                        if target != None {
                            source +>:Rel:+> target;
                        }
                    }
                }
            }
        }
    }

    resolved: list[str] = [];
    if package_node.valid {
        document_node: Part | None = None;
        for part in package_node.parts {
            if part.path == "word/document.xml" {
                document_node = part;
