    parent_id: str = ""
) -> Task | None {
    if task_id in board.tasks { return None; }
    if profile_name not in board.profiles { return None; }

    if parent_id == "" {
        task = Task(tid=task_id, owner=profile_name, root_id=task_id);
        board.tasks[task_id] = task;
        return task;
