"""Synthetic graph model for xurble/django-feed-reader#48."""

node SubscriptionRoot {
    has name: str;
}

node Subscription {
    has sid: str;
    has user_id: str;
    has is_folder: bool = False;
}

node Post {
    has pid: str;
    has user_id: str;
    has is_read: bool = False;
}

edge Membership {}
edge Parent {}
edge Item {}

obj SubscriptionGraph {
    has graph_anchor: SubscriptionRoot;
    has subscriptions: dict[str, Subscription] = {};
    has posts: dict[str, Post] = {};
}

walker SubscriptionWalk {
    has claimed: dict[str, bool] = {};
    has found_subscriptions: list[Subscription] = [];
    has found_posts: list[Post] = [];

    can step_sub with Subscription entry {
        key: str = "s:" + here.sid;
        if key in self.claimed { skip; }
        self.claimed[key] = True;
        self.found_subscriptions.append(here);
        print(here.sid);
        for child in [here ->:Parent:->][?:Subscription] {
            visit :0: [child];
        }
        for post in [here ->:Item:->][?:Post] {
            visit :0: [post];
        }
    }

    can step_post with Post entry {
        key: str = "p:" + here.pid;
        if key in self.claimed { skip; }
        self.claimed[key] = True;
        self.found_posts.append(here);
        print(here.pid);
    }
}

def new_graph -> SubscriptionGraph {
    anchor = SubscriptionRoot(name="subscriptions");
    return SubscriptionGraph(graph_anchor=anchor);
}

def add_subscription(
    graph: SubscriptionGraph,
    sid: str,
    user_id: str,
    is_folder: bool
) -> bool {
    if sid in graph.subscriptions { return False; }
    sub = Subscription(sid=sid, user_id=user_id, is_folder=is_folder);
    graph.subscriptions[sid] = sub;
    graph.graph_anchor +>:Membership:+> sub;
    return True;
}

def add_post(
    graph: SubscriptionGraph,
    sid: str,
    pid: str,
    user_id: str,
    is_read: bool
) -> bool {
    if sid not in graph.subscriptions { return False; }
    if pid in graph.posts { return False; }
    sub: Subscription = graph.subscriptions[sid];
    if sub.user_id != user_id { return False; }
    post = Post(pid=pid, user_id=user_id, is_read=is_read);
    graph.posts[pid] = post;
    sub +>:Item:+> post;
    return True;
}

def set_parent(
    graph: SubscriptionGraph,
    child_id: str,
    parent_id: str
) -> bool {
    if child_id not in graph.subscriptions { return False; }
    if parent_id not in graph.subscriptions { return False; }
    child: Subscription = graph.subscriptions[child_id];
    parent_node: Subscription = graph.subscriptions[parent_id];
    if child_id == parent_id { return False; }
    if parent_node.is_folder == False { return False; }
    if child.user_id != parent_node.user_id { return False; }

    walk = child spawn SubscriptionWalk(claimed={});
    for seen in walk.found_subscriptions {
        if seen.sid == parent_id { return False; }
    }
    parent_node +>:Parent:+> child;
    return True;
}

def unread_count(graph: SubscriptionGraph, sid: str) -> int {
    if sid not in graph.subscriptions { return 0; }
    start: Subscription = graph.subscriptions[sid];
    walk = start spawn SubscriptionWalk(claimed={});
    total: int = 0;
    for post in walk.found_posts {
        if post.user_id == start.user_id and post.is_read == False {
            total += 1;
        }
    }
    return total;
}

def get_unread_posts(graph: SubscriptionGraph, sid: str) -> list[str] {
    ids: list[str] = [];
    if sid not in graph.subscriptions { return ids; }
    start: Subscription = graph.subscriptions[sid];
    walk = start spawn SubscriptionWalk(claimed={});
    for post in walk.found_posts {
        if post.user_id == start.user_id and post.is_read == False {
            ids.append(post.pid);
        }
    }
    return sorted(ids);
}

def get_paginated_posts(
    graph: SubscriptionGraph,
    sid: str,
    limit: int,
    offset: int
) -> list[str] {
    page: list[str] = [];
    if limit <= 0 { return page; }
    if offset < 0 { offset = 0; }
    ids: list[str] = get_unread_posts(graph, sid);
    index: int = offset;
    end: int = offset + limit;
    while index < len(ids) and index < end {
        page.append(ids[index]);
        index += 1;
    }
    return page;
}

def mark_read(graph: SubscriptionGraph, sid: str) -> int {
    if sid not in graph.subscriptions { return 0; }
    start: Subscription = graph.subscriptions[sid];
    walk = start spawn SubscriptionWalk(claimed={});
    changed: int = 0;
    for post in walk.found_posts {
        if post.user_id == start.user_id and post.is_read == False {
            post.is_read = True;
            changed += 1;
        }
    }
    return changed;
}

def get_unread_subscription_list_for_user(
    graph: SubscriptionGraph,
    user_id: str
) -> list[str] {
    ids: list[str] = [];
    for sid in graph.subscriptions {
        sub: Subscription = graph.subscriptions[sid];
        if sub.user_id == user_id and unread_count(graph, sid) > 0 {
            ids.append(sid);
        }
    }
    return sorted(ids);
}
