def newGraph -> LearningGraph {
    graph_root: GraphRoot = GraphRoot();
    return LearningGraph(graph=graph_root);
}

def addKc(graph: LearningGraph, cid: str, title: str, pacer: str, bloom: int) -> KnowledgeComponent {
    finder = graph.graph spawn GraphWalker(mode="find_kc", target=cid);
    if finder.found_kc != None {
        existing: KnowledgeComponent = finder.found_kc;
        return existing;
    }
    item: KnowledgeComponent = KnowledgeComponent(cid=cid, title=title, pacer=pacer, bloom=bloom);
    graph.graph +>:Contains:+> item;
    return item;
}

def addDependency(graph: LearningGraph, prerequisite_id: str, dependent_id: str, confidence: float) -> bool {
    pre_finder = graph.graph spawn GraphWalker(mode="find_kc", target=prerequisite_id);
    if pre_finder.found_kc == None {
        return False;
    }
    dependent_finder = graph.graph spawn GraphWalker(mode="find_kc", target=dependent_id);
    if dependent_finder.found_kc == None {
        return False;
    }
    prerequisite: KnowledgeComponent = pre_finder.found_kc;
    dependent: KnowledgeComponent = dependent_finder.found_kc;
    dependent +>:DependsOn(confidence=confidence, evidence="material"): +> prerequisite;
    return True;
}

def addExercise(graph: LearningGraph, eid: str, prompt: str, kc_id: str) -> bool {
    exercise_finder = graph.graph spawn GraphWalker(mode="find_exercise", target=eid);
    if exercise_finder.found_exercise != None {
        return False;
    }
    kc_finder = graph.graph spawn GraphWalker(mode="find_kc", target=kc_id);
    if kc_finder.found_kc == None {
        return False;
    }
    item: Exercise = Exercise(eid=eid, prompt=prompt);
    graph.graph +>:Contains:+> item;
    concept: KnowledgeComponent = kc_finder.found_kc;
    item +>:Covers:+> concept;
    return True;
}

def sanitizeDependencies(graph: LearningGraph, pairs: list[list[str]]) -> list[list[str]] {
    clean: list[list[str]] = [];
    for pair in pairs {
        if len(pair) >= 2 {
            left = graph.graph spawn GraphWalker(mode="find_kc", target=pair[0]);
            right = graph.graph spawn GraphWalker(mode="find_kc", target=pair[1]);
            if left.found_kc != None {
                if right.found_kc != None {
                    clean.append([pair[0], pair[1]]);
                }
            }
        }
    }
    return clean;
}

def getPrerequisiteChain(graph: LearningGraph, kc_id: str) -> list[str] {
    walker = graph.graph spawn GraphWalker(mode="closure", target=kc_id);
    return sorted(walker.ids);
}

def getGraphNeighborhood(graph: LearningGraph, kc_id: str) -> list[str] {
    walker = graph.graph spawn GraphWalker(mode="neighborhood", target=kc_id);
    return sorted(walker.ids);
}

def getExercisesForKc(graph: LearningGraph, kc_id: str) -> list[str] {
    walker = graph.graph spawn GraphWalker(mode="exercise_for_kc", target=kc_id);
    return sorted(walker.ids);
}
