"""JoNil-Botta/typelisp#6982 — propagate static-library native link requirements."""

node Package {
    has name: str;
    has manifest_root: str;
    has kind: str = "binary";
    has all_links: list[str] = [];
    has linux_links: list[str] = [];
    has windows_links: list[str] = [];
    has search_paths: list[str] = [];
    has raw_args: list[str] = [];
}

edge Depends {}

walker LinkPlanWalker {
    has target: str;
    has focus: str = "";
    has origin: str = "";
    has claimed: dict[str, bool] = {};
    has plan: list[str] = [];

    can add_unique(value: str) {
        if value not in self.plan {
            self.plan.append(value);
        }
    }

    can collect with Package entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;

        include: bool = False;
        if self.focus != "" {
            if here.name == self.focus {
                include = True;
            }
        } else if here.name == self.origin || here.kind == "staticlib" {
            include = True;
        }

        if include {
            for path in here.search_paths {
                resolved: str = path;
                absolute: bool = False;
                if len(path) > 0 && path[0] == "/" {
                    absolute = True;
                } else if len(path) > 1 && path[1] == ":" {
                    absolute = True;
                }
                if absolute == False {
                    resolved = here.manifest_root + "/" + path;
                }
                self.add_unique("-L" + resolved);
            }

            for value in here.all_links {
                self.add_unique(value);
            }
            if self.target == "linux" {
                for value in here.linux_links {
                    self.add_unique(value);
                }
            } else if self.target == "windows" {
                for value in here.windows_links {
                    self.add_unique(value);
                }
            }
            for value in here.raw_args {
                self.add_unique(value);
            }
        }

        print(here.name);
        for dependency in [here ->:Depends:->][?:Package] {
            visit :0: [dependency];
        }
    }
}

def add_dependency(package: Package, dependency: Package) {
    package +>:Depends:+> dependency;
}

def add_link(package: Package, target: str, value: str) {
    if target == "all" {
        package.all_links.append(value);
    } else if target == "linux" {
        package.linux_links.append(value);
    } else if target == "windows" {
        package.windows_links.append(value);
    }
}

def build_link_plan(graph_root: Package, target: str) -> list[str] {
    walker = graph_root spawn LinkPlanWalker(
        target=target,
        origin=graph_root.name
    );
    return walker.plan;
}

def build_named_link_plan(
    graph_root: Package,
    package_name: str,
    target: str
) -> list[str] {
    walker = graph_root spawn LinkPlanWalker(
        target=target,
        focus=package_name,
        origin=graph_root.name
    );
    return walker.plan;
}

with entry {
    root spawn LinkPlanWalker(target="linux");
}
