# iss_PingoLee__PormG.jl__459.jac

node PormModel {
    has cid: str;
}

edge CascadeEdge {}

obj DeletionCollector {
    has objects: dict[str, list[str]] = {};
    has models: dict[str, PormModel] = {};
}

walker CascadeCollector {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with PormModel entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        self.found.append(here.cid);
        print("collect " + here.cid);

        kids: list[PormModel] = [];
        for kid in [here ->:CascadeEdge:->][?:PormModel] {
            kids.append(kid);
        }
        visit :0: [kid];
    }
}

def register_model(collector: DeletionCollector, model: PormModel) -> None {
    collector.models[model.cid] = model;
}

def add_objects_to_collector(
    collector: DeletionCollector,
    model: PormModel,
    keys: list[str]
) -> None {
    if model.cid not in collector.models {
        collector.models[model.cid] = model;
    }
    if model.cid not in collector.objects {
        collector.objects[model.cid] = [];
    }
    for key in keys {
        collector.objects[model.cid].append(key);
    }
}

def find_related_objects(
    collector: DeletionCollector,
    model: PormModel,
    keys: list[str]
) -> list[str] {
    if model.cid not in collector.models {
        return [];
    }

    related: list[str] = [];
    for kid in [model ->:CascadeEdge:->][?:PormModel] {
        related.append(kid.cid);
    }
    return sorted(related);
}

def process_collector(
    collector: DeletionCollector,
    start_id: str
) -> list[str] {
    if start_id not in collector.models {
        return [];
    }

    start_node: PormModel = collector.models[start_id];
    w = start_node spawn CascadeCollector(claimed={}, found=[]);

    # Apply collection changes only after the OSP walk is complete.
    for model_id in w.found {
        if model_id not in collector.objects {
            collector.objects[model_id] = [];
        }
    }
    return sorted(w.found);
}
