# PROGRAM iss_F3-Nation__f3-nation__917.jac

node Org {
    has oid: str;
    has org_type: str;
}

edge ParentChild {}

obj OrgTree {
    has graph_root: Org | None = None;
}

walker FindOrg {
    has wanted: str;
    has claimed: dict[str, bool] = {};
    has found: Org | None = None;

    can locate with Org entry {
        if here.oid in self.claimed {
            skip;
        }
        self.claimed[here.oid] = True;
        print("find " + here.oid);
        if here.oid == self.wanted {
            self.found = here;
            disengage;
        }
        for child in [here ->:ParentChild:->][?:Org] {
            visit :0: [child];
        }
    }
}

walker Descendants {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can collect with Org entry {
        if here.oid in self.claimed {
            skip;
        }
        self.claimed[here.oid] = True;
        self.found.append(here.oid);
        print("descendant " + here.oid);
        for child in [here ->:ParentChild:->][?:Org] {
            visit :0: [child];
        }
    }
}

walker Ancestors {
    has user_org_id: str;
    has required_role: str;
    has claimed: dict[str, bool] = {};
    has allowed: bool = False;

    can climb with Org entry {
        if here.oid in self.claimed {
            skip;
        }
        self.claimed[here.oid] = True;
        print("ancestor " + here.oid);
        if here.oid == self.user_org_id && self.required_role == "admin" {
            self.allowed = True;
        }
        for parent in [here <-:ParentChild:<-][?:Org] {
            visit :0: [parent];
        }
    }
}

def checkHasRoleOnOrg(
    tree: OrgTree,
    user_org_id: str,
    target_org_id: str,
    role: str
) -> bool {
    if tree.graph_root is None {
        return False;
    }
    graph_root: Org = tree.graph_root;
    finder = graph_root spawn FindOrg(wanted=target_org_id);
    if finder.found is None {
        return False;
    }
    target: Org = finder.found;
    w = target spawn Ancestors(
        user_org_id=user_org_id,
        required_role=role
    );
    return w.allowed;
}

def getDescendantOrgIds(tree: OrgTree, org_id: str) -> list[str] {
    ids: list[str] = [];
    if tree.graph_root is None {
        return ids;
    }
    graph_root: Org = tree.graph_root;
    finder = graph_root spawn FindOrg(wanted=org_id);
    if finder.found is None {
        return ids;
    }
    origin: Org = finder.found;
    w = origin spawn Descendants();
    return sorted(w.found);
}

def getEditableOrgIdsForUser(
    tree: OrgTree,
    user_org_id: str,
    role: str
) -> list[str] {
    ids: list[str] = [];
    if tree.graph_root is None {
        return ids;
    }
    graph_root: Org = tree.graph_root;
    finder = graph_root spawn FindOrg(wanted=user_org_id);
    if finder.found is None {
        return ids;
    }
    if role != "admin" {
        ids.append(user_org_id);
        return ids;
    }
    return getDescendantOrgIds(tree, user_org_id);
}
