    max_expanded: int = 268435456,
    max_entries: int = 4096,
    cancelled: bool = False,
    revoked: bool = False
) -> PackageHandle {
    pkg = PackageHandle();
    seen: dict[str, bool] = {};
    has_types: bool = False;
    has_document: bool = False;

    if cancelled {
        pkg.accepted = False;
        pkg.disposed = True;
