            pkg.evidence.append("reject:macro:" + spec.path);
        }
        if spec.executable {
            pkg.accepted = False;
            pkg.evidence.append("reject:executable:" + spec.path);
        }
        if spec.compression != "deflate" {
            if spec.compression != "store" {
                pkg.accepted = False;
                pkg.evidence.append("reject:compression:" + spec.path);
            }
        }
        pkg.compressed_total = pkg.compressed_total + spec.compressed;
        pkg.expanded_total = pkg.expanded_total + spec.expanded;
        if spec.role == "content_types" {
            has_types = True;
        }
        if spec.role == "document" {
            has_document = True;
        }
    }

    if pkg.compressed_total > max_compressed {
        pkg.accepted = False;
        pkg.evidence.append("reject:compressed-limit");
    }
    if pkg.expanded_total > max_expanded {
        pkg.accepted = False;
        pkg.evidence.append("reject:expanded-limit");
    }
    if has_types == False {
