def get_subscription(graph_root: Subscription, sid: str) -> Subscription | None {
    w = graph_root spawn LookupWalk(target=sid, claimed={});
    return w.found;
}

def set_parent(child: Subscription, parent: Subscription) -> bool {
    if child.sid == parent.sid {
        return False;
    }
    if child.user_id != parent.user_id {
        return False;
    }
    if not parent.is_folder {
        return False;
    }

    w = child spawn HierarchyWalk(claimed={});
    for item in w.items {
        if item.sid == parent.sid {
            return False;
        }
    }

    parent +>:ParentOf:+> child;
    return True;
}

def get_unread_posts(sub: Subscription) -> list[str] {
    w = sub spawn HierarchyWalk(claimed={});
    posts: list[str] = [];
    for item in w.items {
        for post in item.unread_posts {
            posts.append(post);
        }
    }
    return posts;
}

def unread_count(sub: Subscription) -> int {
    return len(get_unread_posts(sub));
}

def get_paginated_posts(
    sub: Subscription, page: int, size: int
) -> list[str] {
    result: list[str] = [];
    if page < 1 or size < 1 {
        return result;
    }

    posts = get_unread_posts(sub);
    start: int = (page - 1) * size;
    stop: int = start + size;
    index: int = 0;

    for post in posts {
        if index >= start and index < stop {
            result.append(post);
        }
        index += 1;
    }
    return result;
}

def mark_read(sub: Subscription) -> int {
    w = sub spawn HierarchyWalk(claimed={});
    for item in w.items {
        item.unread_posts = [];
    }
    return len(w.items);
}

def get_unread_subscription_list_for_user(
    user_id: str, graph_root: Subscription
) -> list[str] {
    w = graph_root spawn HierarchyWalk(claimed={});
    ids: list[str] = [];
    for item in w.items {
        if item.user_id == user_id and len(item.unread_posts) > 0 {
            ids.append(item.sid);
        }
    }
    return sorted(ids);
}
