                }
            }
        }
    }
}

walker ExerciseWalk {
    has claimed: dict[str, bool] = {};
    has found: list[str] = [];

    can step_concept with Concept entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print(here.slug);
        for exercise in [here ->:ExerciseFor:->][?:Exercise] {
            visit :0: [exercise];
        }
    }

    can step_exercise with Exercise entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        self.found.append(here.exercise_id);
        print(here.exercise_id);
    }
