def new_material(material_id: str) -> Material {
    material = Material(material_id=material_id);
    return material;
}

def ingest_concepts(material: Material, slugs: list[str]) -> list[str] {
    added: list[str] = [];
    for slug in slugs {
        if slug not in material.concepts {
            concept = Concept(slug=slug, title=slug);
            material.concepts[slug] = concept;
            material +>:HasConcept:+> concept;
            added.append(slug);
        }
    }
    return added;
}

def concept_of(material: Material, slug: str) -> Concept | None {
    if slug in material.concepts {
        return material.concepts[slug];
    }
    return None;
}

def dependency_would_cycle(dependent: Concept, prerequisite: Concept) -> bool {
    w = dependent spawn ConceptWalk(
        claimed={},
        target=prerequisite.slug,
        forward=True
    );
    return w.hit;
}

def ingest_dependencies(
    material: Material,
    raw_edges: list[list[str]]
) -> list[list[str]] {
    accepted: list[list[str]] = [];
    for pair in raw_edges {
        if len(pair) == 2 {
            if pair[0] in material.concepts && pair[1] in material.concepts {
                dependent = material.concepts[pair[0]];
                prerequisite = material.concepts[pair[1]];
                if !dependency_would_cycle(dependent, prerequisite) {
                    prerequisite +>:Depends:+> dependent;
                    accepted.append([pair[0], pair[1]]);
                }
            }
        }
    }
    return accepted;
}

def prerequisite_chain(start: Concept) -> list[str] {
    w = start spawn ConceptWalk(claimed={}, forward=False);
    return w.found;
}

def add_exercise(
    material: Material,
    exercise_id: str,
    prompt: str
) -> Exercise {
    if exercise_id in material.exercises {
        return material.exercises[exercise_id];
    }
    exercise = Exercise(exercise_id=exercise_id, prompt=prompt);
    material.exercises[exercise_id] = exercise;
    material +>:HasExercise:+> exercise;
    return exercise;
}

def link_exercise(
    material: Material,
    exercise_id: str,
    concept_slug: str
) -> bool {
    if exercise_id not in material.exercises {
        return False;
    }
    if concept_slug not in material.concepts {
        return False;
    }
    concept = material.concepts[concept_slug];
    exercise = material.exercises[exercise_id];
    concept +>:ExerciseFor:+> exercise;
    return True;
}

def exercises_for(concept: Concept) -> list[str] {
    w = concept spawn ExerciseWalk(claimed={});
    return w.found;
}
