"""JoNil-Botta/typelisp#6982
Propagate static-library native link requirements into final binary plans.
"""

node Package {
    has name: str;
    has kind: str;
    has manifest: str;
    has root_path: str;
}

node LinkRequirement {
    has declared_by: str;
    has manifest: str;
    has manifest_field: str;
    has target: str;
    has mode: str;
    has value: str;
}

edge Depends {}
edge Exports {}

def _resolve_path(base: str, path: str) -> str {
    if path.startswith("/") {
        return path;
    }
    if len(path) > 1 {
        if path[1] == ":" {
            return path;
        }
    }
    return base + "/" + path;
}

walker FindPackage {
    has sought: str;
    has claimed: dict[str, bool] = {};
    has found: Package | None = None;

    can locate with Package entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print("lookup " + here.name);
        if here.name == self.sought {
            self.found = here;
        }
        deps = [here ->:Depends:->][?:Package];
        visit :0: deps;
    }
}

walker LinkPlan {
    has target: str;
    has claimed: dict[str, bool] = {};
    has emitted: dict[str, bool] = {};
    has values: list[str] = [];
    has provenance: list[str] = [];

    can collect_package with Package entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        print("link-package " + here.name);

        deps = [here ->:Depends:->][?:Package];
        visit :0: deps;

        if here.kind == "binary" or here.kind == "staticlib" {
            reqs = [here ->:Exports:->][?:LinkRequirement];
            visit :0: reqs;
        }
    }

    can collect_requirement with LinkRequirement entry {
        if here.target != "all" and here.target != self.target {
            skip;
        }

        effective = here.value;
        if here.mode == "path" {
            effective = _resolve_path(here.declared_by, here.value);
        }

        key = here.mode + "|" + effective;
        if key in self.emitted {
            skip;
        }
        self.emitted[key] = True;
        self.values.append(effective);
        self.provenance.append(
            here.declared_by + "@" + here.manifest + ":" +
            here.manifest_field + "=" + effective
        );
        print("link-need " + effective);
    }
}

def make_package(
    name: str,
    kind: str,
    manifest: str = "package.toml",
    root_path: str = "."
) -> Package {
    return Package(
        name=name,
        kind=kind,
        manifest=manifest,
        root_path=root_path
    );
}

def add_requirement(
    owner: Package,
    mode: str,
    value: str,
    target: str = "all",
    manifest_field: str = "link"
) -> LinkRequirement {
    req = LinkRequirement(
        declared_by=owner.root_path,
        manifest=owner.manifest,
        manifest_field=manifest_field,
        target=target,
        mode=mode,
        value=value
    );
    owner +>:Exports:+> req;
    return req;
}

def find_package(graph_root: Package, package_name: str) -> Package | None {
    w = graph_root spawn FindPackage(sought=package_name, claimed={});
    return w.found;
}

def link_plan(graph_root: Package, target: str) -> list[str] {
    w = graph_root spawn LinkPlan(target=target, claimed={});
    return w.values;
}

def link_metadata(graph_root: Package, target: str) -> list[str] {
    w = graph_root spawn LinkPlan(target=target, claimed={});
    return w.provenance;
}
