            joined = joined + "/" + part;
        }
    }

    if len(joined) == 0 {
        return "-L" + manifest_dir;
    }
    if len(manifest_dir) > 0 and manifest_dir[len(manifest_dir) - 1] == "/" {
        return "-L" + manifest_dir + joined;
