            pkg.reason = "forbidden-content";
            _record(pkg, "forbidden:" + name);
        }
    }

    if not found_doc {
        pkg.valid = False;
        pkg.reason = "missing-document";
        _record(pkg, "missing:word/document.xml");
    }
    if pkg.compressed_bytes > MAX_COMPRESSED
        or pkg.expanded_bytes > MAX_EXPANDED {
        pkg.valid = False;
        pkg.reason = "package-size-limit";
    }

    if relationships != None {
        for i in range(len(relationships)) {
            if i >= len(parts) {
                _record(pkg, "orphan-relationship-source");
                continue;
            }
            for target in relationships[i] {
                if _external_target(target) {
                    _record(pkg, "external:" + target);
                    continue;
                }
                if _unsafe_path(target) {
                    _record(pkg, "unsafe-target:" + target);
                    continue;
                }
                target_part: Part | None = None;
                for candidate in parts {
                    if candidate.name == target {
                        target_part = candidate;
                    }
                }
                if target_part == None {
                    _record(pkg, "unknown-target:" + target);
                    continue;
                }
                parts[i] +>:RelationshipEdge:+> target_part;
            }
        }
    }
    return pkg;
}

def resolve_package(pkg: Package) -> list[str] {
    found: list[str> = [];
    if not pkg.valid {
        return found;
    }
    w = pkg spawn ResolveWalker(claimed={});
    found = sorted(w.found);
    return found;
}

def package_evidence(pkg: Package) -> list[str] {
    return sorted(pkg.evidence);
}
