        self.claimed[here.cid] = True;
        print("audit stream");
        if self.mode == "stream" && here.wid == self.wanted {
            self.found = here;
        }
        if self.mode == "deps" {
            if here.wid != self.wanted && here.promoted == False {
                self.deps_ok = False;
            }
            for pre in [here ->:Depends:->][?:Workstream] {
                visit :0: [pre];
            }
        }
    }

    can audit_gate with GateNode entry {
        if here.cid in self.claimed { skip; }
        self.claimed[here.cid] = True;
        print("audit gate");
        if self.mode == "gate" && here.gid == self.wanted {
            self.gate_ok = here.verified;
        }
    }
}

def new_control -> Control {
    graph_root = ControlRoot(label="DM-IMP");
    ctl = Control(graph_root=graph_root);
    return ctl;
}

def add_gate(ctl: Control, gid: str, verified: bool = False) -> bool {
    if gid in ctl.gates { return False; }
    gate = GateNode(gid=gid, verified=verified);
    ctl.gates[gid] = gate;
    ctl.graph_root +>:Protects:+> gate;
    return True;
}

def verify_gate(ctl: Control, gid: str) -> bool {
    if gid not in ctl.gates { return False; }
    ctl.gates[gid].verified = True;
    return True;
}

def add_stream(ctl: Control, sid: str, title: str, gate_id: str = "") -> bool {
    if sid in ctl.streams { return False; }
    ws = Workstream(wid=sid, title=title, gate_id=gate_id);
    ctl.streams[sid] = ws;
    ctl.graph_root +>:Contains:+> ws;
    return True;
}

def add_dependency(ctl: Control, dependent_id: str, prerequisite_id: str) -> bool {
    dependent = _find_stream(ctl, dependent_id);
    prerequisite = _find_stream(ctl, prerequisite_id);
    if dependent == None or prerequisite == None { return False; }
    dependent +>:Depends:+> prerequisite;
    return True;
}

def record_evidence(ctl: Control, sid: str) -> bool {
    ws = _find_stream(ctl, sid);
    if ws == None { return False; }
    ws.evidence = True;
    return True;
}

def _find_stream(ctl: Control, sid: str) -> Workstream | None {
    if sid not in ctl.streams { return None; }
    w = ctl.graph_root spawn Audit(mode="stream", wanted=sid);
    return w.found;
}

def _gate_ready(ctl: Control, gid: str) -> bool {
    if gid not in ctl.gates { return False; }
    w = ctl.graph_root spawn Audit(mode="gate", wanted=gid);
    return w.gate_ok;
}

def _dependencies_ready(ctl: Control, sid: str) -> bool {
    w = ctl.graph_root spawn Audit(mode="deps", wanted=sid);
    return w.deps_ok;
}

def promote_stream(ctl: Control, sid: str) -> bool {
    ws = _find_stream(ctl, sid);
    if ws == None { return False; }
    if ws.promoted { return True; }
    if ws.evidence == False { return False; }
    if ws.gate_id != "" && _gate_ready(ctl, ws.gate_id) == False {
        return False;
    }
    if _dependencies_ready(ctl, sid) == False { return False; }
    ws.promoted = True;
    ws.stage = "Robust";
    return True;
}

def configure_license(ctl: Control, field: str, minimum: int, bps: int) -> bool {
    plan = LicensePlan(field=field, minimum_commitment=minimum, royalty_bps=bps);
    ctl.license_plan = plan;
    ctl.graph_root +>:LicenseLink:+> plan;
    return True;
}

def commercial_ready(ctl: Control) -> bool {
    if ctl.license_plan == None { return False; }
    for sid in ctl.streams {
        ws = _find_stream(ctl, sid);
        if ws == None || ws.promoted == False { return False; }
    }
    return True;
}

def royalty_due(ctl: Control, revenue: int) -> int {
    if revenue <= 0 || commercial_ready(ctl) == False {
        return 0;
    }
    if ctl.license_plan == None { return 0; }
    if revenue < ctl.license_plan.minimum_commitment { return 0; }
    return revenue * ctl.license_plan.royalty_bps // 10000;
}
