"""OSP lift for xurble/django-feed-reader#48."""

node FeedRoot {}

edge ParentOf {}

node Subscription {
    has sid: str;
    has user_id: str;
    has is_folder: bool = False;
    has parent_sid: str = "";
    has unread_posts: list[str] = [];
}

obj FeedStore {
    has graph_root: FeedRoot;
    has subscriptions: dict[str, Subscription] = {};
}

walker CycleWalker {
    has target_sid: str;
    has found: bool = False;
    has claimed: dict[str, bool] = {};

    can scan with Subscription entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        print(here.sid);
        if here.sid == self.target_sid {
            self.found = True;
        }
        for kid in [here ->:ParentOf:->][?:Subscription] {
            visit :0: [kid];
        }
    }
}

walker UnreadWalker {
    has user_id: str;
    has posts: list[str] = [];
    has targets: list[Subscription] = [];
    has claimed: dict[str, bool] = {};

    can collect with Subscription entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        print(here.sid);
        if here.user_id != self.user_id { skip; }
        self.targets.append(here);
        for post in here.unread_posts {
            self.posts.append(post);
        }
        if here.is_folder {
            for kid in [here ->:ParentOf:->][?:Subscription] {
                if kid.user_id == self.user_id {
                    visit :0: [kid];
                }
            }
        }
    }
}

walker UnreadListWalker {
    has user_id: str;
    has items: list[Subscription] = [];
    has claimed: dict[str, bool] = {};

    can collect_root with FeedRoot entry {
        print("subscriptions");
        for kid in [here ->:ParentOf:->][?:Subscription] {
            visit :0: [kid];
        }
    }

    can collect_sub with Subscription entry {
        if here.sid in self.claimed { skip; }
        self.claimed[here.sid] = True;
        print(here.sid);
        if here.user_id != self.user_id { skip; }
        if len(here.unread_posts) > 0 {
            self.items.append(here);
        }
        if here.is_folder {
            for kid in [here ->:ParentOf:->][?:Subscription] {
                visit :0: [kid];
            }
        }
    }
}

def make_store() -> FeedStore {
    return FeedStore(graph_root=FeedRoot());
}

def create_subscription(
    store: FeedStore,
    sid: str,
    user_id: str,
    is_folder: bool,
    unread_posts: list[str]
) -> Subscription {
    if sid in store.subscriptions {
        return store.subscriptions[sid];
    }
    posts: list[str] = [];
    for post in unread_posts {
        posts.append(post);
    }
    sub = Subscription(
        sid=sid,
        user_id=user_id,
        is_folder=is_folder,
        unread_posts=posts
    );
    store.subscriptions[sid] = sub;
    store.graph_root +>:ParentOf:+> sub;
    return sub;
}

def set_parent(store: FeedStore, child_id: str, parent_id: str) -> bool {
    if child_id not in store.subscriptions {
        return False;
    }
    if parent_id not in store.subscriptions {
        return False;
    }
    child = store.subscriptions[child_id];
    parent = store.subscriptions[parent_id];
    if child.sid == parent.sid {
        return False;
    }
    if child.user_id != parent.user_id {
        return False;
    }
    if parent.is_folder == False {
        return False;
    }
    if child.parent_sid != "" {
        return False;
    }
    w = parent spawn CycleWalker(target_sid=child.sid, claimed={});
    if w.found {
        return False;
    }
    parent +>:ParentOf:+> child;
    child.parent_sid = parent.sid;
    return True;
}

def get_unread_posts(store: FeedStore, subscription_id: str) -> list[str] {
    if subscription_id not in store.subscriptions {
        return [];
    }
    sub = store.subscriptions[subscription_id];
    w = sub spawn UnreadWalker(user_id=sub.user_id, claimed={});
    return w.posts;
}

def unread_count(store: FeedStore, subscription_id: str) -> int {
    return len(get_unread_posts(store, subscription_id));
}

def get_paginated_posts(
    store: FeedStore,
    subscription_id: str,
    page: int,
    page_size: int
) -> list[str] {
    result: list[str] = [];
    if page < 1 or page_size < 1 {
        return result;
    }
    posts = get_unread_posts(store, subscription_id);
    start: int = (page - 1) * page_size;
    stop: int = start + page_size;
    index: int = 0;
    for post in posts {
        if index >= start and index < stop {
            result.append(post);
        }
        index += 1;
    }
    return result;
}

def mark_read(store: FeedStore, subscription_id: str) -> None {
    if subscription_id not in store.subscriptions {
        return None;
    }
    sub = store.subscriptions[subscription_id];
    w = sub spawn UnreadWalker(user_id=sub.user_id, claimed={});
    for target in w.targets {
        target.unread_posts = [];
    }
    return None;
}

def get_unread_subscription_list_for_user(
    store: FeedStore,
    user_id: str
) -> list[Subscription] {
    w = store.graph_root spawn UnreadListWalker(user_id=user_id, claimed={});
    return w.items;
}
