def sanitizeConceptRefs(concepts: list[KC], refs: list[str]) -> list[str] {
    known: dict[str, bool] = {};
    accepted: dict[str, bool] = {};
    clean: list[str] = [];
    for concept in concepts {
        known[concept.slug] = True;
    }
    for ref in refs {
        if ref in known {
            if ref not in accepted {
                accepted[ref] = True;
                clean.append(ref);
            }
        }
    }
    return clean;
}

