def _unsafe_kind(name: str) -> bool {
    if name.endswith(".exe") { return True; }
    if name.endswith(".dll") { return True; }
    if name.endswith(".com") { return True; }
    if name.endswith(".bin") and name.find("vba") >= 0 { return True; }
    return False;
}

def _allowed_content_type(kind: str) -> bool {
