    updated: bool = false;
    for gate in [graph_root ->:Contains:->][?:LicenseGate] {
        gate.approved = approved;
        updated = true;
    }
    return updated;
}

def licensing_ready(graph_root: ControlPlane) -> bool {
    all_evidence: bool = true;
    all_claims: bool = true;
    gate_ok: bool = false;

    for ws in [graph_root ->:Contains:->][?:Workstream] {
        if not ws.evidence {
            all_evidence = false;
        }
    }
    for claim in [graph_root ->:Contains:->][?:Claim] {
        if not claim.verified {
            all_claims = false;
        }
    }
    for gate in [graph_root ->:Contains:->][?:LicenseGate] {
        if gate.approved {
            gate_ok = true;
        }
    }
    return all_evidence and all_claims and gate_ok;
}
