def build_control_plane -> ControlPlane {
    plan = ControlPlane(name="DM-IMP");
    w177 = Workstream(key="177", title="IP and claim map");
    w178 = Workstream(key="178", title="Reproducible SOTA evidence");
    w179 = Workstream(key="179", title="FPGA timing and resource proof");
    w180 = Workstream(key="180", title="Codec-aware media adapters");
    w181 = Workstream(key="181", title="Formal verification and fuzzing");
    w182 = Workstream(key="182", title="Licensing and design wins");

    plan +>:Contains:+> w177;
    plan +>:Contains:+> w178;
    plan +>:Contains:+> w179;
    plan +>:Contains:+> w180;
    plan +>:Contains:+> w181;
    plan +>:Contains:+> w182;

    w178 +>:DependsOn:+> w177;
    w181 +>:DependsOn:+> w177;
    w179 +>:DependsOn:+> w181;
    w179 +>:DependsOn:+> w178;
    w180 +>:DependsOn:+> w179;
    w182 +>:DependsOn:+> w180;

    gate_names: list[str] = [
        "counsel",
        "benchmark",
        "hardware",
        "codec",
        "security",
        "evaluation",
        "licensee"
    ];
    for name in gate_names {
        gate = LicenseGate(name=name, approved=False);
        plan +>:Contains:+> gate;
    }
    return plan;
}

def audit_control_plane(plan: ControlPlane) -> list[str] {
    w = plan spawn AuditWalker(claimed={});
    return sorted(w.keys);
}

def gate_status(plan: ControlPlane, name: str) -> bool {
    for gate in [plan ->:Contains:->][?:LicenseGate] {
        if gate.name == name {
            return gate.approved;
        }
    }
    return False;
}

def promotion_ready(plan: ControlPlane, key: str) -> bool {
    target: Workstream | None = None;
    for item in [plan ->:Contains:->][?:Workstream] {
        if item.key == key {
            target = item;
        }
    }
    if target is None {
        return False;
    }
    for gate in [plan ->:Contains:->][?:LicenseGate] {
        if gate.approved == False {
            return False;
        }
    }
    w = target spawn DependencyWalker(claimed={});
    return w.all_complete;
}
