def ingest_docx(config: IngestInput) -> dict[str, list[str]] {
    accepted: list[str] = [];
    rejected: list[str] = [];
    evidence: list[str] = [];
    seen: dict[str, bool] = {};
    compressed_total: int = 0;
    expanded_total: int = 0;
    required: list[str] = ["[Content_Types].xml", "word/document.xml"];
    result: dict[str, list[str]] = {};
    result["accepted"] = [];
    result["rejected"] = [];
    result["evidence"] = [];
    result["resolved"] = [];
    result["disposed"] = [];

    if config.cancelled {
        rejected.append("cancelled");
    }
    if len(config.entry_names) > config.max_entries {
        rejected.append("entry-count");
    }

    for name in config.entry_names {
        if name in seen {
            rejected.append("duplicate:" + name);
            continue;
        }
        seen[name] = True;
        safe: bool = True;
        if name == "" or name.startswith("/") {
            safe = False;
        } else {
            segments: list[str] = name.split("/");
            for segment in segments {
                if segment == "" or segment == ".." {
                    safe = False;
                }
            }
        }
        if !safe {
            rejected.append("traversal:" + name);
            continue;
        }
        if name not in config.compressed or name not in config.expanded
            or name not in config.kinds {
            rejected.append("missing-metadata:" + name);
            continue;
        }
        compressed_total += config.compressed[name];
        expanded_total += config.expanded[name];
        kind: str = config.kinds[name];
        if kind == "malformed" or kind == "unsupported"
            or kind == "macro" or kind == "exe" or kind == "encrypted" {
            rejected.append(kind + ":" + name);
            evidence.append("omitted:" + name);
            continue;
        }
        accepted.append(name);
    }

    if compressed_total > config.max_compressed {
        rejected.append("compressed-limit");
    }
    if expanded_total > config.max_expanded {
        rejected.append("expanded-limit");
    }
    for needed in required {
        if needed not in accepted {
            rejected.append("required:" + needed);
        }
    }
    for source_name in config.relationships {
        if source_name not in accepted {
            evidence.append("unknown-source:" + source_name);
        }
        for target_name in config.relationships[source_name] {
            if target_name.startswith("http://")
                or target_name.startswith("https://")
                or target_name.startswith("file:") {
                rejected.append("external:" + target_name);
                evidence.append("omitted:" + target_name);
            } else if target_name not in accepted {
                evidence.append("unknown-target:" + target_name);
            }
        }
    }

    if len(rejected) > 0 {
        result["rejected"] = sorted(rejected);
        result["evidence"] = sorted(evidence);
        result["disposed"].append("true");
        return result;
    }

    graph_root = Package(package_id=config.package_id);
    parts: list[Part] = [];
    for name in accepted {
        part = Part(name=name, kind=config.kinds[name]);
        graph_root +>:Contains:+> part;
        parts.append(part);
    }
    for source_name in config.relationships {
        source: Part | None = None;
        for part in parts {
            if part.name == source_name {
                source = part;
            }
        }
        if source != None {
            for target_name in config.relationships[source_name] {
                target: Part | None = None;
                for part in parts {
                    if part.name == target_name {
                        target = part;
                    }
                }
                if target != None {
                    source +>:Depends:+> target;
                }
            }
        }
    }

    w = graph_root spawn Resolve(claimed={});
    graph_root.disposed = True;
    result["accepted"] = sorted(accepted);
    result["evidence"] = sorted(evidence);
    result["resolved"] = sorted(w.found);
    result["disposed"].append("true");
    return result;
}
