test "diamond revisit is collected once" {
    store = FeedStore();
    a = create_subscription(store, "a", "u", True, []);
    b = create_subscription(store, "b", "u", True, ["b"]);
    c = create_subscription(store, "c", "u", True, ["c"]);
    d = create_subscription(store, "d", "u", False, ["d"]);
    a +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    b +>:ParentOf:+> d;
    c +>:ParentOf:+> d;
    assert (unread_count(store, "a") == 3);
    assert (get_unread_posts(store, "a") == ["b", "c", "d"]);
    unread = get_unread_subscription_list_for_user(store, "u");
    assert (len(unread) == 3);
}

test "unknown identifiers are tolerated" {
    store = FeedStore();
    assert (lookup(store, "missing") is None);
    assert (unread_count(store, "missing") == 0);
    assert (get_unread_posts(store, "missing") == []);
    assert (get_paginated_posts(store, "missing", 1, 2) == []);
    assert (mark_read(store, "missing") == 0);
    assert (not set_parent(store, "missing", "also-missing"));
    assert (len(get_unread_subscription_list_for_user(store, "missing")) == 0);
}

test "invalid parent relationships are rejected" {
    store = FeedStore();
    create_subscription(store, "folder", "u1", True, []);
    create_subscription(store, "child", "u1", False, []);
    create_subscription(store, "other", "u2", True, []);
    create_subscription(store, "feed", "u1", False, []);
    assert (not set_parent(store, "child", "child"));
    assert (not set_parent(store, "child", "other"));
    assert (not set_parent(store, "child", "feed"));
    assert (set_parent(store, "child", "folder"));
    assert (set_parent(store, "child", "folder"));
}

test "legacy cycle terminates and valid nesting paginates" {
    store = FeedStore();
    x = create_subscription(store, "x", "u", True, ["x"]);
    y = create_subscription(store, "y", "u", True, ["y"]);
    x +>:ParentOf:+> y;
    y +>:ParentOf:+> x;
    assert (unread_count(store, "x") == 2);
    assert (get_unread_posts(store, "x") == ["x", "y"]);

    folder = create_subscription(store, "folder", "v", True, ["a"]);
    child = create_subscription(store, "child", "v", False, ["b", "c"]);
    assert (set_parent(store, "child", "folder"));
    assert (get_paginated_posts(store, "folder", 1, 2) == ["a", "b"]);
    assert (get_paginated_posts(store, "folder", 2, 2) == ["c"]);
    assert (mark_read(store, "folder") == 3);
    assert (unread_count(store, "folder") == 0);
}
